pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead space penalty: small-but-nonzero leftovers are the worst waste.
    if post_residual > 0 {
        // Quadratic penalty for tiny residuals (< 10% capacity), the "unusable zone".
        if frac < 0.10 {
            score += 120.0 * (0.10 - frac) * 10.0;
        }
        // Modulo classes: residuals divisible by common item granularities
        // (multiples of 10, 5) are more reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 18.0;
        } else if r % 5 == 0 {
            score -= 8.0;
        }
        // Integer-division threshold classes on post_residual.
        let class = r / 10; // 0..10 harmonic class
        score += class as f64 * 3.0; // prefer leaving larger, more usable residual
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt = next_item_size as f64;
            let slack = (post_residual - next_item_size) as f64;
            if post_residual == next_item_size {
                score -= 220.0; // chained perfect fit
            } else {
                // Favor tight co-fit; penalize if leftover after next item is tiny.
                let post2 = slack;
                if post2 > 0.0 && post2 / cap < 0.05 {
                    score += 30.0;
                }
                score -= 40.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot fit here: mild penalty, this bin is a dead end soon.
            score += 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
        // But penalize wasting a nearly-full bin's last-chance on a bad fit.
        if post_residual > 0 && frac < 0.05 {
            score += 60.0;
        }
    }

    // Stream progression: early on, be more willing to spread items (open bins),
    // later consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (mean_residual / cap);

    // Prefer bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Default new-bin score slightly above a decent existing fit.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // Compete with last-chance bin: only win if that bin would be wrecked.
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect / graded near-perfect fit rewards (strengthened).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    } else if post_residual <= 25 {
        score -= 4.0;
    }

    // Dead-space shaping: small unusable leftovers penalized smoothly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 10.0 * (0.5 + 0.5 * tightness);
        // Modulo reusability classes.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 14.0;
        } else if r % 5 == 0 {
            score -= 6.0;
        }
        // Small dead-space trap (borrowed from best heuristic).
        if r < 10 {
            score += 25.0;
        }
    }

    // Lookahead: next item cannot fit in the leftover — likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 35.0 + (next_item_size - post_residual) as f64 * 0.7;
    }

    // Two-item lookahead chain (strong exact-match reward).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits with slack: reward proportional to closeness.
        score -= 60.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Three-item chain: residual after next item still hosts a third item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 40.0;
        } else if r2 <= 5 {
            score -= 15.0;
        } else if r2 <= 12 {
            score -= 6.0;
        } else if r2 > 30 {
            score += 3.0;
        }
    }

    // Last-chance bonus: sole fitting bin should absorb unless fit is wrecked.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
        if post_residual > 0 && (post_residual as f64) / cap < 0.05 {
            score += 60.0;
        }
    }

    // Consolidation: prefer bins tighter than fleet mean residual.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.25;

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Residual drift toward mean residual harmonizes mergeability.
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / cap).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Stream progression shaping.
    score += post_residual as f64 * progress * 0.3;
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size as f64 > 0.75 * cap {
            score -= 20.0;
        }
        // Small items should almost never open fresh bins.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fleet slack gate: opening a bin wasteful when pooled slack is ample.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // Preserve room for a large next item when fleet slack can't host it.
        if next_item_size > 0 && next_item_size as f64 > 0.55 * cap
            && next_item_size > item_size && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Fragmentation guard: awkward 31–40 band when fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation for multi-item chains.
    if next_item_size > 1 && bin_residual > next_item_size && bin_residual % next_item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals (graded harder for very small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10.0 - post_residual as f64) * 3.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Prefer bins tighter than average (slightly sharpened).
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when an open bin's residual exceeds item+next.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0 + fitting_bins_count as f64 * 2.0;
        }
        let unabsorbed = (item_size as f64 - mean_residual).max(0.0);
        if unabsorbed > 0.0 {
            score -= (unabsorbed / cap) * 30.0;
        }
        // Opening a fresh bin is acceptable only if the fleet's mean
        // slack cannot even cover half the item; scale by coverage.
        let cover = (mean_residual / (item_size as f64).max(1.0)).min(2.0);
        if cover < 0.5 {
            score -= (0.5 - cover) * 60.0;
        }
        // If the next item would strand in a fresh bin while some open
        // bin's post-residual can host it, penalize opening a new bin.
        if next_item_size > 0 && next_item_size <= item_size {
            let fresh_post = bin_capacity - item_size;
            if next_item_size as f64 > fresh_post as f64
                && mean_residual - item_size as f64 >= next_item_size as f64 {
                score += 30.0;
            }
        }
        // Count-based slack absorption.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // NEW: fresh-bin dead-space forecast — a fresh bin's leftover
        // (cap - item) is only valuable if it can plausibly absorb the
        // next item or the fleet's typical item; otherwise penalize.
        if next_item_size > 0 {
            let fresh_post = (bin_capacity - item_size) as f64;
            if fresh_post < next_item_size as f64
                && fresh_post < mean_residual.max(1.0) {
                score += 25.0;
            }
        }
        // NEW: late-stream fresh bins are almost always wasteful when any
        // open bin fits — escalate the penalty with remaining stream.
        let remaining_items = total_items.saturating_sub(step_index) as f64;
        let rem_frac0 = (remaining_items / total_items.max(1) as f64).min(1.0);
        if fitting_bins_count >= 1 && rem_frac0 > 0.4 {
            score += rem_frac0 * 18.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened quartic near-full fill.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (graded by gap).
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk — sparse zones accumulate dead space under tight fleets.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal — chain fits.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio — prime targets.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term — homogenize residuals for future items.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement — reward room for plausible mid-size
    // future items while substantial work remains.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Exact two-item seal — post_residual equals next item plus the
    // current item's size (perfect chain closure), sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: dead-space recovery potential — a post_residual that can host
    // the mean item size (item_size) is a future-fill asset; reward it
    // proportionally to how much stream remains, with a sweet-spot band
    // around half capacity where mixed-size items are most likely to fit.
    if post_residual > 0 && rem_frac > 0.15 {
        let pr = post_residual as f64;
        if pr >= item_size as f64 {
            score -= 5.0 * rem_frac * (0.4 + tightness);
        }
        let half = 0.5 * cap;
        let band = ((pr - half).abs() / half).min(1.0);
        if band < 0.25 {
            score -= (0.25 - band) * 12.0 * rem_frac;
        }
    }

    // NEW: wasted-dead-space integral — penalize residuals that are too
    // small for the current item's typical successors, scaled by fleet
    // pressure so tight fleets avoid stranding small gaps.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns && pr < item_size as f64 * 0.5 {
            score += (ns - pr) * 0.45 * (0.5 + tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward dead space.
            let dead = next_item_size - post_residual;
            score += 8.0 * dead as f64;
        }
    }

    // Penalize large unusable residual (below typical minimum item size range).
    if post_residual < 10 {
        score -= 30.0; // near-perfect fill, strongly prefer
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good packing candidates).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Slight penalty for spreading across too many open bins early in stream.
    if open_bins_count > 1 && post_residual > bin_capacity as u32 / 2 {
        score += 5.0;
    }

    // New-bin candidate: make it unattractive unless current bin would be left
    // with unusable sliver or no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual > 0
            && (next_item_size > post_residual) && (next_item_size - post_residual) > 30;
        if !bad_fit {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Derived context (hoisted so all terms can use them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    let tightness = 1.0 - (mean_residual / cap).min(1.0);

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10.0 - post_residual as f64) * 3.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0 + fitting_bins_count as f64 * 2.0;
        }
        let unabsorbed = (item_size as f64 - mean_residual).max(0.0);
        if unabsorbed > 0.0 {
            score -= (unabsorbed / cap) * 30.0;
        }
        // Opening a fresh bin is acceptable only if the fleet's mean
        // slack cannot even cover half the item; scale by coverage.
        let cover = (mean_residual / (item_size as f64).max(1.0)).min(2.0);
        if cover < 0.5 {
            score -= (0.5 - cover) * 60.0;
        }
        // If the next item would strand in a fresh bin while some open
        // bin's post-residual can host it, penalize opening a new bin.
        if next_item_size > 0 && next_item_size <= item_size {
            let fresh_post = bin_capacity - item_size;
            if next_item_size as f64 > fresh_post as f64
                && mean_residual - item_size as f64 >= next_item_size as f64 {
                score += 30.0;
            }
        }
        // Count-based slack absorption.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // Fresh-bin dead-space forecast: penalize stranded slivers.
        if next_item_size > 0 {
            let fresh_post = (bin_capacity - item_size) as f64;
            if fresh_post < next_item_size as f64 && fresh_post < 0.12 * cap {
                score += 25.0;
            }
        }
        // NEW: fresh-bin residual quality — reward large reusable leftovers,
        // penalize stranded slivers, scaled by remaining stream.
        let fresh_post = (bin_capacity - item_size) as f64;
        if fresh_post >= 0.4 * cap {
            score -= 14.0 * rem_frac;
        } else if fresh_post < 0.1 * cap && next_item_size > 0 {
            score += 18.0 * rem_frac;
        }
        // NEW: fresh-bin lookahead pair — if the fresh bin could host both
        // this item and the next (cap >= item + next), opening is cheap.
        if next_item_size > 0
            && (item_size + next_item_size) as f64 <= cap
            && fresh_post < next_item_size as f64 {
            score -= 20.0 * rem_frac;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream.
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Post-residual usability score.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let hosts_next = pr >= next_item_size as f64;
        let hosts_small = pr >= 0.2 * cap && pr <= 0.45 * cap;
        if hosts_next || hosts_small {
            score -= 10.0 * rem_frac;
        } else if pr < 0.2 * cap {
            score += 9.0 * rem_frac * (1.0 - pr / (0.2 * cap));
        }
    }

    // Exact two-item seal — perfect chain closure, sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — easy-to-refill leftovers.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: combined fine-grained fit + lookahead — when the post-residual
    // exactly equals the next item (perfect seal) and the fleet has few
    // fitting bins, amplify the reward to lock in compaction chains.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
        score -= 12.0 * (0.5 + rem_frac);
    }

    // NEW: dead-space budget — penalize residuals that are too small for
    // the next item but too large to be "perfect", weighted by how much
    // stream remains, so early-stream dead space is punished harder.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 0.15 * cap {
            score += deficit * 1.2 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
