    } else if post_residual < 10 {
        score -= 30.0; // near-perfect, dead space negligible
    } else if post_residual < 25 {
        score -= 10.0;
    } else if post_residual > 80 {
        score += 15.0; // leaving a huge gap suggests poor bin choice
    }

    // Modulo-10 harmonic class: residues divisible by 10 align with common item sizes.
    let harmonic = post_residual % 10;
    score += harmonic as f64 * 0.8;

    // Integer-division thresholds: how many "average" items still fit?
    let avg_item = 45.0f64;
    let fits_left = (post_residual as f64 / avg_item).floor();
    score -= fits_left * 4.0;

    // Lookahead coupling: does this bin still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residues that stay in a "usable class" for the next item.
            score -= 12.0;
            let pair_waste = post_residual - next_item_size;
            score += (pair_waste % 10) as f64 * 0.5;
        } else {
            score += 8.0; // bin becomes dead after this placement
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open a new bin if current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        // Prefer new bin when mean residual is low and stream is early.
        score = 20.0 + 40.0 * crowding - 15.0 * progress;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

