        // Exact match for next item: very strong reward
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 90.0 + 0.3 * mean_residual;
    }

    // Early stream: slightly discourage hoarding open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that is still hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are nearly useless
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mildly penalize leaving medium gaps
            if post_residual >= next_item_size / 2 {
                score += 3.0;
            }
        }
    } else {
        // Last item: just minimize leftover, standard.
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins exist.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, scaled by how fragmented current bins are.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 20.0 + 10.0 * fragmentation + open_bins_count as f64 * 0.5;

        // Early in the stream, opening bins is cheaper (build diversity of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (consolidate small leftovers).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for using more-open bins over proliferating bins.
    score += 0.05 * open_bins_count as f64;

    // Dynamic time horizon: as stream nears end, avoid opening bins at all costs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its non-linear shaping
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // early on, waste is cheap; later, dead space is penalized more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * pr_norm;
    score *= progress_coupling;

    // Reward tight fits: post-residual near zero gets a bonus
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize leaving residuals that are awkward (just above typical small item sizes)
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            // next item cannot fit here; residual becomes dead space, worse late in stream
            score += 3.0 * (1.0 + 2.0 * progress) * (nxt - pr) / cap;
        } else {
            // next item fits: reward smooth in gap size
            score -= 2.5 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + progress);
    }

    // Many open bins: prefer consolidating into existing bins over spreading
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * open_norm * pr_norm;

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (i.e., fuller bins get a mild reward)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 1.5 * dev * (1.0 + progress);

    // Mild penalty for a brand-new empty bin candidate, weakening late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in a
    // "small-item friendly" residue band are more valuable to preserve.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> pairs naturally with many sizes
    let class_a = (post_residual % 10 == 0) as f64;
    // Class B: post_residual in the tight-dead-zone (1..10) -> near-waste
    let class_b = ((1..10).contains(&post_residual)) as f64;
    // Class C: post_residual exactly 0 -> perfect closure, strong reward
    let class_c = (post_residual == 0) as f64;

    score -= 12.0 * class_c;
    score -= 4.0 * class_a;
    score += 18.0 * class_b;

    // Integer-division tiers on post_residual: quarter bands of capacity
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 8.0,                    // 0..25: nearly full, good
        1 => 2.0,                    // 25..50
        2 => 0.0,                    // 50..75
        _ => -3.0,                   // large residual: empty-ish bin, mild reward
    };

    // Coupling with lookahead: if next item fits the post-residual exactly,
    // reward heavily; if it cannot fit, this residual is dead weight.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 6.0;
        }
        // Harmonic pairing: next_item_size and post_residual share a factor of 5
        if next_item_size % 5 == 0 && post_residual % 5 == 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is small relative
    // to capacity and open-bin residuals are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let penalty = 25.0 - 10.0 * fragmentation - 8.0 * progress
            - if item_size <= 30 { 6.0 } else { 0.0 };
        score += penalty.max(0.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += (11.0 - gap) * 6.0; // dead space in 1..10 range
        } else if gap <= 20.0 {
            score += (21.0 - gap) * 1.5; // moderately awkward gap
        }
    }

    // Reward very tight fits (post_residual small but nonzero is still penalized above,
    // so give a compensating bonus when the item nearly fills the bin).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 12.0 * (tightness - 0.9) / 0.1;
    }

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new bin is cheaper so favor fresh bins slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits into the resulting gap, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // gap left behind that next item cannot use: mild penalty
        score += 2.0;
    }

    // New empty bin candidate: neutral baseline; only attractive when existing
    // residuals are poor (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 5.0 {
            score -= 3.0; // existing bins are tight-ish, opening fresh is fine
        } else {
            score += 4.0; // prefer reusing open bins when they have room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain of two perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize wasted lookahead potential
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 50.0).min(1.5);
        }
    }

    // Compare post_residual to mean residual: leaving less than average is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when all open bins would leave large waste
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but attractive if the item is large and open bins are fragmented
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        if fragmentation > 20.0 {
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter bins overall
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * (fit_ratio - 0.85) * 6.67;
    }

    // Penalize dead space that nothing small could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // worst kind of sliver
    } else if post_residual >= 10 {
        // Usable leftovers are mildly penalized proportional to waste.
        score += 0.15 * post_residual as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, this is a great chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // If next item is large and would not fit here afterwards, slight penalty
    // unless the fit here was already tight.
    if next_item_size > post_residual && fit_ratio < 0.7 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if crowd > 2.0 {
        score -= 8.0 * fit_ratio * progress.min(1.0);
    }

    // Mean residual divergence: bins far below mean residual are "fresh";
    // prefer dumping items into below-average (fuller) bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.1 * residual_gap;

    // New-bin candidate: normally penalized, but attractive when the current
    // fit is poor and the next item is large (preserve big residual for it).
    if bin_residual == bin_capacity {
        score += 55.0;
        let poor_fit = fit_ratio < 0.5;
        let big_next = next_item_size >= 60;
        if poor_fit && big_next {
            score -= 70.0;
        } else if poor_fit && fitting_bins_count <= 2 {
            score -= 30.0;
        } else if big_next && next_item_size > post_residual + 20 {
            score -= 20.0;
        }
        // Late in the stream, new bins are cheap to avoid; dampen new-bin appeal.
        score += 20.0 * progress;
    }

    // Early stream: be conservative, keep bins balanced for future flexibility.
    if progress < 0.2 {
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial shrink factor over stream progress
    let shrink = 1.0 + 0.6 * progress - 0.3 * progress * progress;
    let mut score = pr * shrink;

    // Non-linear dead-space penalty: convex in normalized post-residual
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post-residual) more strongly late in the stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: smooth quadratic reward if next item fits post-residual
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = pr - n;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 6.0 * (1.0 - g * g) * (0.5 + 0.5 * progress);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild penalty for bin proliferation relative to stream length
    score += (open_bins_count as f64) * (1.0 - progress) * 0.05;

    // Deviation from mean residual: prefer bins with residuals near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make empty bins slightly less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: partition capacity into 4 quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 (4 only when residual==capacity, new bin)
    match class {
        0 => score -= 60.0,  // near-perfect fit: dead space < 25
        1 => score -= 15.0,  // usable residual 25..49
        2 => score += 0.0,   // mediocre 50..74
        3 => score += 20.0,  // large waste 75..99 (unless empty bin)
        _ => {}
    }

    // Empty new-bin candidate: neutral baseline, slightly penalized so we prefer
    // reusing open bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        score = 85.0 + open_bins_count as f64;
        // If no other bin fits well, opening fresh is fine
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: reward if next item fits snugly into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        if next_leftover < quarter {
            score -= 35.0; // chain two tight fits together
        } else if next_leftover < 2 * quarter {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual at all -> residual is dead space
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize creating tiny unusable slivers (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Late in the stream, be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.25;

    // Prefer bins with residual below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that no item (min size 1..100, but practically
    // small gaps < 15) can ever be filled are pure waste. Penalize harshly.
    if post_residual < 15 && post_residual > 0 {
        score += (15 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones; a brand-new bin (residual == capacity) gets penalized
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 3.0;
    } else {
        // Slight bonus for using an existing bin as open-bin count grows.
        score -= (open_bins_count as f64).ln() * 4.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly prefer this bin (chains two items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 15 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean residual (keeps
    // residual distribution balanced, leaving larger bins for large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early in the stream, be more willing to open new bins (exploration);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep neutral-ish baseline, slightly high so it only wins
    // when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        return 100.0 + 0.25 * mean_residual;
    }

    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // --- 2-step lookahead core: does post_residual exactly/loosely fit next item? ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled by next item.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward, scaled by how tight the chain is.
            let tightness = 1.0 - (post - nxt) / 100.0;
            score -= 25.0 * tightness;
        } else {
            // Dead space below next item size: penalize unusable gap.
            let gap = nxt - post;
            score += 0.9 * gap;
            // Small residuals (<10) are nearly useless: extra penalty.
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // --- Relative-to-mean coupling: prefer bins whose residual deviates favorably ---
    let dev = post - mean_residual;
    score += 0.15 * dev;

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- Tight fit reward: small post_residual means good space utilization now ---
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64 - item_size as f64).max(0.0);

    // --- Late-stream consolidation: as stream progresses, prefer filling existing bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    // Slight preference for bins already partially filled (fragmentation control)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 * (-tightness / 6.0).exp();

    // Penalize large dead space relative to the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < next_item_size.min(10) {
            score += 10.0; // blocks likely next fit
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are not chosen for good fits.
        score += 30.0;
        // But if many bins compete and mean residual is high (fragmentation),
        // opening a fresh bin is more attractive.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If very few bins fit the item, new bin is a reasonable fallback.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    if !is_new_bin {
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Global balance: slightly favor bins below mean residual (keep big holes free).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let norm_it = it / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 1.5 * progress * norm_pr + 2.0 * progress * progress * norm_pr * norm_it);

    let mut score = poly;

    // Tight fits are rewarded smoothly
    score -= 0.8 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let diff = norm_pr - nxt;
        if diff >= 0.0 {
            score -= 0.5 * diff * (1.0 - diff);
        } else {
            score += 1.2 * diff * diff;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.0;
    }

    // Mild penalty for deviating from mean residual (keeps bins balanced)
    score += 0.1 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize slightly unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 0.3 + 2.0 * (1.0 - norm_it);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize small-but-nonzero residuals (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable
    let common = [10u32, 20, 25, 30, 40, 50];
    let mut reusable = false;
    for &c in &common {
        if post_residual % c == 0 && post_residual > 0 {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 15.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Integer division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability reward, stronger for tight coupling
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here -> this residual likely wasted
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 40.0;
        // early stream: allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Prefer filling bins below mean residual (balance / tightest bins first)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Many open bins: encourage closing them out (fill high-fill bins)
    score -= (open_bins_count as f64).sqrt() * (cap - bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (or for the lookahead item) are wasted forever.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // truly dead space
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the next item either: heavy penalty
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer
    // packing into existing bins when dead space is comparable.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate: only attractive when no open bin gives a decent fit,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0; // open bins could host it reasonably; deprioritize new bin
        }
        if post_residual as f64 > 0.65 * bin_capacity as f64 {
            score -= 15.0; // large item: fresh bin is natural
        }
    }

    // Prefer bins whose residual is tight relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Mild stream-progress coupling: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (low post_residual)
    score += (bin_residual as f64) * 0.05;

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            // Perfect 2-step chain: next item exactly fills this bin
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward closeness of the chain
            score -= 20.0 + 0.5 * (post_residual as f64 - nx);
        } else {
            // Next item won't fit: penalize leaving awkward dead space
            score += 0.4 * (nx - post_residual as f64);
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Compare against mean residual: bins below mean residual are "tighter" -> favor
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    } else {
        // New empty bin candidate: penalize mildly unless item is large relative to capacity
        score += 10.0 + 0.2 * (bin_capacity as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize large dead space (post_residual hard to reuse)
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // tiny slivers are fine-ish, mildly reward
    } else if post_residual >= 10 {
        score += (post_residual as f64).powf(1.15) * 0.6;
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items or when mean residual is fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bin if item fits snugly somewhere (large item relative to mean residual)
        if (item_size as f64) > mean_residual * 0.8 {
            score += 50.0; // keep using open bins for large items if they roughly fit
        } else {
            score -= 30.0 * (1.0 - fragmentation) * (1.0 - progress);
        }
        // lookahead: if next item is large, fresh bin is valuable
        if next_item_size as f64 >= post_residual as f64 && next_item_size > 0 {
            score += 20.0;
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 40.0; // next item can slot into this fresh bin's leftover
        }
    } else {
        // Lookahead synergy: post_residual exactly fits next item
        if next_item_size > 0 {
            if next_item_size as u32 == post_residual {
                score -= 120.0;
            } else if (next_item_size as u32) <= post_residual {
                score -= 25.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
            }
        }
        // Slightly prefer fuller bins when many bins are open
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Mild time-varying tightening: later in stream, discourage waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Encourage consolidation when mean residual is low
    if mean_residual < 30.0 && bin_residual >= item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly tolerate residual; late: penalize dead space quadratically.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += norm_pr * norm_pr * cap * (0.5 + 2.0 * w_late);
    score -= w_early * norm_pr * 10.0;

    // Reward bins whose post-residual can still fit the next item (smooth gate via ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr / nxt).min(1.0);
        score -= 15.0 * fits * fits;
        // Penalize post-residual that is just barely too small for next item (dead space trap).
        let gap = (pr - nxt) / cap;
        if gap < 0.0 {
            score += (-gap) * cap * (0.3 + progress);
        }
    }

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Prefer denser bins: deviation from mean residual, smoothly weighted.
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * cap * 0.5;

    // Mild preference for filling existing bins over opening new ones, stronger late.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 + progress);

    // New-bin candidate: smooth penalty unless residual is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * (1.0 - norm_pr) * (1.0 - norm_pr) + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (small enough
    // that a typical item fills them) are rewarded; dead-space classes penalized.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual.
    let quarter = post_residual / 25;           // 0..4 harmonic class
    let dead = post_residual < 10;              // unusable sliver

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if dead {
        score += 25.0; // create sliver only if nothing better
    }

    // Modulo arithmetic on post_residual: residuals congruent to small
    // multiples of common item sizes (10,20,25,50) are "fillable" classes.
    let fillable = (post_residual % 10 == 0 && post_residual <= 50)
        || (post_residual % 25 == 0 && post_residual <= 75)
        || (post_residual % 20 == 0 && post_residual <= 60);
    if fillable {
        score -= 12.0;
    }

    // Penalize mid-range dead zones (residuals that few items can use).
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }
    if post_residual >= 21 && post_residual <= 24 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly-ish,
    // this placement chains well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual && (post_residual - next_item_size) <= 10 {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; leftover becomes true dead space
            score += frac * 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current residual is a bad class
    // or the item is large relative to residual (poor fit).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.85 || dead {
            score -= 20.0; // prefer fresh bin for big items / bad leftovers
        } else {
            score += 15.0; // keep using existing decent bins
        }
    } else {
        // Prefer tighter existing bins: reward small relative waste.
        let waste = post_residual as f64 / bin_residual.max(1) as f64;
        score += waste * 10.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mild tie-break toward filling bins with larger residuals when mean
    // residual is high (spread load), low otherwise.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Quarter-class harmonic nudge: even classes slightly preferred.
    if quarter % 2 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals smaller than the smallest possible
    // item (1) are impossible, but residuals that cannot host the lookahead
    // item are likely wasted if the gap is small relative to item size.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // scale penalty by how "unusable" the gap is for typical items
        let gap_deficit = (next_item_size - post_residual) as f64;
        let avg_item = 100.0 / 3.0; // rough expected mean item scale
        let unusability = gap_deficit / avg_item;
        score += 20.0 + unusability * 45.0;
    }

    // Strong near-perfect fit rewards, sharpened with a continuous curve
    // instead of flat bands so ties between close fits break correctly.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 5 {
        score -= 30.0 + (5 - post_residual) as f64 * 2.0;
    } else if post_residual <= 15 {
        score -= 10.0 + (15 - post_residual) as f64 * 1.2;
    }

    // Lookahead trade-off: if this bin's post_residual exactly hosts the
    // next item, that's a chain fit — reward it to enable 2-item sequences.
    if post_residual > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance pressure: only fitting bin gets a strong stay bonus,
    // but relax it when the resulting fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let terrible = post_residual as f64 > 0.5 * bin_capacity as f64;
        if !terrible {
            score -= 35.0;
        } else {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage spreading, but taper it as the stream
    // advances so late-stage compaction dominates over bin-count thrift.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.45 - 0.2 * progress);

    // New-bin candidate logic: open a fresh bin when open bins would leave
    // a bad gap, i.e. when mean residual is much smaller than the item, or
    // when the item is large and would dominate any open bin.
    if bin_residual == bin_capacity {
        score += 50.0;
        if mean_residual >= item_size as f64 {
            score += 30.0; // open bins host it reasonably; keep new bin last
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0; // large item: fresh bin is natural
        }
        // If no open bin can leave a usable gap for the next item, opening
        // a fresh bin preserves flexibility.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 12.0;
        }
    }

    // Tightness coupling: prefer residuals close to the item, with a
    // quadratic term so very loose fits are penalized super-linearly.
    let slack = (bin_residual - item_size) as f64;
    score += slack * 0.06 + slack * slack * 0.0015;

    // Stream-progress coupling: tighten packing as the stream advances.
    score += post_residual as f64 * progress * 0.35;

    // Mean-residual anchoring: when this bin's residual is far below the
    // mean residual, it's a scarce tight slot — use it for small items now.
    if (bin_residual as f64) < mean_residual * 0.6 && item_size as f64 > bin_residual as f64 * 0.7 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residual below min item size is wasted forever.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead coupling: penalize gaps that cannot host the next item,
    // scaled by how large the unreachable gap is.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 45.0 + (next_item_size - post_residual) as f64 * 0.9;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual <= 5 {
        score -= 28.0;
    } else if post_residual <= 15 {
        score -= 9.0;
    }

    // Last-chance pressure: sole fitting bin gets a strong preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure with saturation: the cost of opening more bins
    // should not grow linearly forever; taper it.
    let oc = open_bins_count as f64;
    score += oc * 0.5 / (1.0 + oc * 0.02);

    // New-bin candidate logic: open a fresh bin only when open bins offer
    // poor fits (mean residual too tight for the item or the next item).
    if bin_residual == bin_capacity {
        score += 50.0;
        if mean_residual >= item_size as f64 {
            score += 30.0;
        }
        // Big items or items that would leave a large post-residual favor new bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin keeps room for it.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Tightness coupling: prefer bins whose residual hugs the item.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.06;

    // Progress-scaled waste penalty: as the stream advances, be stricter
