        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when the post-fit residual there would be
        // worse than the best open-bin post residual can be.
        if fitting_bins_count > 1 {
