            score -= 14.0;
        } else if r > next_item_size && (r - next_item_size) <= 3 {
            score -= 6.0;
        }
    }

    // NEW: waste-avoidance for large items — placing a big item (> 60) into a
    // bin with slack slightly larger than the item strands a tiny remainder;
    // prefer bins where the remainder is either 0 or comfortably reusable.
    if item_size > 60 && bin_residual > item_size {
        let r = bin_residual - item_size;
        if r > 0 && r < 6 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
