        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Last-chance pressure: sole fitting bin should generally absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure scaled by tightness of the fleet.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Dead-space ratio penalty — residual too small relative to typical
    // small items is likely stranded; scale penalty by how unusable it is.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Reward bins whose post-fit residual aligns with mean residual of the
    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // New-bin candidate handling with sharper gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when the post-fit residual there would be
        // worse than the best open-bin post residual can be.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        // Stronger gate — if the fleet's mean residual comfortably covers
        // the item, opening a fresh bin wastes that pooled slack.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never justify a fresh bin when any
        // open bin fits them.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items also deserve a stricter fresh-bin gate when
        // multiple open bins fit — consolidation beats spreading.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bins are attractive when the next item is large and
        // no open bin could host it — leave the fleet residuals untouched.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // When the current item nearly fills a fresh bin, the fresh-bin
        // option is excellent (post_residual tiny) — deepen the discount.
        if item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 18.0;
        }
        // NEW: fresh-bin attractiveness decays with the number of competing
        // open bins — with many open bins, pooled slack is precious.
        if fitting_bins_count >= 3 {
            score += (fitting_bins_count as f64 - 2.0) * 3.0;
        }
        // NEW: opening a fresh bin early in the stream is cheap insurance
        // for future large items; late in the stream it wastes capacity.
        let early_progress = step_index as f64 / total_items.max(1) as f64;
        if early_progress < 0.25 {
            score -= 6.0;
        } else if early_progress > 0.8 {
            score += 8.0;
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: gently prefer bins whose residual stays usable
    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation — a bin whose residual is a multiple of the
    // next item size enables multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — penalize residuals in the awkward 31–40 band
    // that rarely fits common items when the fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Pair-fit lookahead — reward placements that leave a residual
    // which, combined with the next item, exactly matches a near-full bin,
    // signalling a future two-item seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if pair as f64 >= 0.95 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Waste-anticipation — penalize residuals that are larger than the
    // next item but leave a useless remainder (< 8) after hosting it, a
    // common source of stranded slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // NEW: next-item hostability bonus — if the next item fits in the
    // post_residual AND the remainder after hosting it is either zero or
    // generously reusable, deepen the reward proportionally to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 6.0 + 6.0 * tightness;
        } else if r2 >= next_item_size {
            // residual can host the next item twice — strong chain potential
            score -= 4.0;
        }
    }

    // NEW: competition-scaled fit reward — when several bins can fit the
    // item, prefer the one leaving the smallest post_residual with extra
    // weight, since poor choices compound across many candidates.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        score += post_residual as f64 * 0.04 * (fitting_bins_count.min(8) as f64);
    }

    score
}

