    // Chain lookahead: residual after next item would still host a third small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

