    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // NEW: absolute usability of the post-fit residual — a leftover that can
    // host the next item OR a generic mid-size item is worth more than raw
    // smallness implies. Weight by how much of the item it can still absorb.
    if post_residual > 0 {
        let cap_f = bin_capacity as f64;
        let usable = if next_item_size > 0 && post_residual >= next_item_size {
            1.0
        } else if post_residual >= 25 {
            0.6
        } else if post_residual >= 10 {
            0.3
        } else {
            0.0
        };
        score -= usable * 6.0 * (1.0 - (post_residual as f64 / cap_f).min(1.0));
    }

