    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose (high mean residual),
    // penalize leaving residuals in the awkward 31–40 band that rarely fits
    // common items, pushing packing toward either tight or large leftovers.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

