    // pre-fit residual is closest to the item size (best-fit reinforcement).
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += gap * 4.0;
    }

    score
}

