    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if pair as f64 >= 0.95 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Waste-anticipation — residual hosting next item but leaving a
    // useless remainder (< 8) is a common source of stranded slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    score
}

