        // nearly stranded — penalize proportionally to how close it came.
        if next_item_size > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += (10.0 - miss) * 0.9 * (1.0 - tightness);
            }
        }
