    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: fleet-slack conservation — when the pooled residual across open
    // bins is only barely enough for the next item, strongly discourage
    // consuming a bin whose post-residual would still be needed later.
    if next_item_size > 0 && mean_residual > 0.0 {
        let coverage = mean_residual / next_item_size as f64;
        if coverage < 1.3 && post_residual > 0 && post_residual < next_item_size {
            score += (1.3 - coverage) * 15.0;
        }
    }

    score
}

