        // placed, opening new bins almost always wastes pooled slack; only
        // allow it when the fleet genuinely cannot host the item.
        let progress0 = step_index as f64 / total_items.max(1) as f64;
        if progress0 > 0.75 && fitting_bins_count >= 1 {
            score += 10.0 * (progress0 - 0.75) / 0.25;
        }
