    // prefer the one whose placement leaves the *largest contiguous usable*
    // remainder among the fleet's small-residual pool; this reduces the
    // number of half-filled bins competing for future items.
    if fitting_bins_count > 1 && post_residual > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        // Bins with large post residuals are "safe" choices when alternatives
        // exist; gently reward keeping tight bins for tighter fits.
        score += (post_residual as f64 / bin_capacity as f64) * 8.0 * scarcity;
