    // leave a useless remainder (< 8), a common source of stranded slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // NEW: two-step usability chain — reward residuals that can host the
    // next item AND still leave a usable (> 12) remainder for future small
    // items, coupling fine-grained fitting with deeper lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 12 && r2 <= 40 {
            score -= (r2 as f64 / 40.0) * 5.0;
        }
    }

    // NEW: consolidation pressure — when many bins are open, mildly favor
    // placements that minimize leftover variance across the fleet, reducing
    // dead-space fragmentation over the stream.
    if open_bins_count > 4 && post_residual > 0 {
        let spread = ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64).min(1.0);
        score += spread * open_bins_count as f64 * 0.15;
    }

    score
}

