        // a new bin almost always costs more than a mediocre open-bin fit,
        // since leftover slack has little remaining chance to be spent.
        let progress0 = step_index as f64 / total_items.max(1) as f64;
        if progress0 > 0.75 && fitting_bins_count >= 1 {
            score += 18.0 * (progress0 - 0.75) / 0.25;
        }
        // NEW: allow fresh bins early when the item is large enough that
        // placing it in an open bin would strand a big residual there.
        if progress0 < 0.25 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: gently prefer bins whose residual stays usable
    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: fitting-count scarcity reward — when very few open bins can host
    // the item, prefer consuming those bins over spreading load; scale the
    // reward inversely with how many options exist.
    if fitting_bins_count >= 1 && bin_residual != bin_capacity {
        score -= (4.0 / fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
