    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible future item are "dead space" — heavily penalize them.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize residuals that cannot fit the lookahead item (wasted capacity
    // relative to what we know is coming next).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual generally good, but extra reward
    // when the fit is near-perfect.
    if post_residual <= 2 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + bin_pressure;
    } else {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Slight bias toward bins with below-average residual (denser bins),
    // keeping looser bins flexible for future items.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

