            } else if fresh_leftover % 10 == 0 {
                score -= 5.0;
            }
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: gently prefer bins whose residual stays usable
    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: dual-residual lookahead — if the next item would fit the post
    // residual AND leave a still-usable third-slot residual, this bin is a
    // strong chain candidate; deepen the existing chain reward smoothly.
    if next_item_size > 1 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 10 {
            score -= 3.0 + (r2.min(30) as f64) * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the leftover space match the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover can host the next item: reward proportionally.
            score -= 30.0 + (post_residual as f64 - next_item_size as f64) * -0.5;
            // Exact match for next item is even better.
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Dead space relative to the next item: penalize.
            score += (next_item_size as f64 - post_residual as f64) * 2.0;
        }
    }

    // Penalize small unusable leftovers (< minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) < next_item_size as f64
            && fitting_bins_count <= 1;
        if poor_fit {
            score -= 40.0;
        } else {
            score += 120.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild preference for tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Fleet tightness: how much slack the fleet holds relative to capacity.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);

    // Dead-space avoidance: residuals too small to host typical small items
    // are stranded capacity — penalize smoothly.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Lookahead: gap that cannot host the next item is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Graded reward for tight fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    // Two-item chain: post_residual exactly hosts the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Chain lookahead: residual after next item hosts a third item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Exact-fit anticipation: residual a multiple of next item size.
    if next_item_size > 1 && bin_residual > next_item_size && bin_residual % next_item_size == 0 {
        score -= 3.0;
    }

    // Last-chance pressure: sole fitting bin absorbs the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Harmonize post-fit residual with fleet mean residual for mergeability.
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / cap).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Continuous usability shaping of small residuals.
    if post_residual > 0 {
        let usability = (post_residual as f64 / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // Fragmentation guard for the awkward 31–40 band.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream preference for usable residuals.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation: keep loose bins early for future large items.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // ---- New-bin candidate gating (borrowed and refined) ----
    if is_new_bin {
        score += 45.0;
        // Opening a fresh bin wastes pooled slack if the fleet covers the item.
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        // Oversized items justify fresh bins.
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        if item_size as f64 > 0.75 * cap {
            score -= 15.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 {
            score -= 12.0;
        }
        // Prefer fresh bins for oversized items that would wreck a bin's residual.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / cap) * 10.0;
        }
        // Stronger gate when pooled slack comfortably covers the item.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never open a fresh bin.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items: consolidation beats spreading.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bin attractive when next item is large and unhostable.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // Slack-ratio gate: opening acceptable only when pooled residual
        // barely exceeds the item.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
    } else {
        // Small consolidation nudge for existing bins.
        score -= 2.0;
        // Tightness relative to the item being placed.
        score += (bin_residual as f64 - item_size as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        score += (post_residual as f64) * 0.5
            + 15.0 * (fitting_bins_count as f64).ln().max(0.0)
            - 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Lookahead coupling: bonus if next item fits into the resulting residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Time horizon: later in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Penalize bins far from the mean residual unless the fit is tight,
    // spreading wear across bins.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

