    }

    // NEW: lookahead-fit coupling — when the next item exactly fits the
    // post residual, and the bin residual also divides cleanly by the item,
    // this bin is part of a perfect multi-item chain; reward more strongly.
    if next_item_size > 0 && post_residual == next_item_size
        && bin_residual % item_size.max(1) == 0
    {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: small residues are dead space.
    // Class by capacity fraction: residues in (0,10] are near-useless for items >=10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer division classes: post_residual / 10 tells how many 10-sized
    // "slots" remain. Reward bins whose leftover is a harmonic multiple of
    // common item classes (10,20,25,50).
    let slots = post_residual / 10;
    score -= 8.0 * slots as f64;

    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0; // residue divisible by 10: reusable by many sizes
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0; // also matches 25-class items
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            // prefer leaving next_left in a good harmonic class
            if next_left % 10 == 0 {
                score -= 30.0;
            }
            score -= 10.0 * (next_left / 10) as f64;
        } else {
            // next item cannot use this bin's residue: penalize proportionally
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits via post_residual (already)
        score += 2.0 * fitting_bins_count as f64;
    }

    // Mean residual context: if this bin is much emptier than average,
    // it is a good "garbage collector" bin.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff;

    // Stream progression: late in stream, be greedy about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: only attractive if no open bin is a decent fit
    // (this is handled by the post_residual == capacity case getting the
    // base value 100 with no harmonic bonuses; add a mild penalty so we
    // prefer filling existing bins unless they fit poorly).
    if bin_residual == bin_capacity {
        score += 40.0;
        // opening new bin is fine early when many items remain
        score -= 20.0 * (1.0 - progress);
    }

    score
}

