    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Small-but-usable residual zone: mild penalty to discourage leaving
    // awkward gaps; larger residuals are progressively fine.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward fits that still accommodate the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }
    // Penalize if the residual kills the next item's fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin by subtracting a bonus (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; also slightly less
        // attractive late in the stream.
        score += 10.0 + pressure + (step_index as f64 / total_items.max(1) as f64) * 8.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (tighter bins get packed first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residual too small for the minimum item is wasted.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead: gap that cannot host the next item is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits, with a graded medium-tight tier.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    // Two-item lookahead chain: post_residual exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Chain lookahead: residual after next item would still host a third small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Last-chance pressure: sole fitting bin should generally absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure scaled by tightness of the fleet.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Dead-space ratio penalty — residual too small relative to typical
    // small items is likely stranded; scale penalty by how unusable it is.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Reward bins whose post-fit residual aligns with mean residual of the
    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Continuous dead-space shaping — smooth "usability curve" penalizing
    // residuals too small to be reliably reusable, scaled by fleet slack.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // NEW: quadratic dead-space ratio — penalize wasted fraction of the bin
    // more aggressively as it grows, pushing toward high-fill placements.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 5.0;

    // NEW: stranded-slack accounting — if the post-fit residual cannot host
    // even the smallest plausible item (<= 10), tax it proportionally to how
    // much capacity is being locked away, amplified late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (0.6 + 1.2 * progress);
    }

    // New-bin candidate handling with sharper gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when the post-fit residual there would be
        // worse than the best open-bin post residual can be.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        // Stronger gate — if the fleet's mean residual comfortably covers
        // the item, opening a fresh bin wastes that pooled slack.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never justify a fresh bin when any
        // open bin fits them.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items also deserve a stricter fresh-bin gate when
        // multiple open bins fit — consolidation beats spreading.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bins are attractive when the next item is large and
        // no open bin could host it — leave the fleet residuals untouched.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // Fresh-bin gate scaled by fleet slack ratio — opening a bin is
        // only acceptable if the pooled residual barely exceeds the item.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // NEW: fresh-bin waste audit — opening a fresh bin locks in
        // (capacity - item) of slack; tax that locked slack relative to the
        // fleet's existing mean residual, unless the next item is huge and
        // would otherwise be stranded.
        let locked = (bin_capacity - item_size) as f64;
        let next_stranded = next_item_size > 0
            && next_item_size as f64 > mean_residual.max(0.0)
            && next_item_size > item_size;
        if !next_stranded {
            score += (locked / bin_capacity as f64) * 18.0 * (0.5 + 0.5 * progress);
        }
        // NEW: late-stream fresh-bin suppression — near the end of the stream
        // consolidation matters most; make fresh bins distinctly worse unless
        // nothing else fits.
        if progress > 0.75 && fitting_bins_count > 1 {
            score += 15.0 * progress;
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: gently prefer bins whose residual stays usable
    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: next-item stranding guard — if the current placement would leave
    // a residual that cannot host the next item while some other placement
    // could, penalize proportionally to the shortfall.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if fitting_bins_count > 1 {
            score += shortfall * 0.25 * (0.5 + tightness);
        }
    }

    score
}

