            score -= 15.0;
        }
    }

    // --- Slight stream-progression pressure: late in the stream, be more frugal ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (resid / bin_capacity as f64);

    score
}

