    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit even a small future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when many bins are open relative to stream length, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0)).min(5.0);
    score -= 3.0 * pressure * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (more crowded) to keep a spread of useful residuals.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        // Opening a new bin leaves residual == capacity - item_size; reward when that's roomy,
        // penalize when open bins could host the item decently.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 {
            score += 10.0 + 20.0 * (1.0 - poor_fit); // discourage abandoning open bins on good fits
