    // Dead-space avoidance: residual too small for the minimum item is wasted.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead: gap that cannot host the next item is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits, with a graded medium-tight tier.
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual <= 5 {
        score -= 27.0;
    } else if post_residual <= 15 {
        score -= 9.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    // Two-item lookahead chain: post_residual exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Chain lookahead: residual after next item would still host a third small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 24.0;
        } else if r2 <= 5 {
            score -= 11.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Last-chance pressure: sole fitting bin should generally absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0;
    }

    // Open-bin pressure scaled by tightness of the fleet.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Dead-space ratio penalty — residual too small relative to typical
    // small items is likely stranded; scale penalty by how unusable it is.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Reward bins whose post-fit residual aligns with mean residual of the
    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Continuous dead-space shaping — smooth "usability curve" penalizing
    // residuals too small to be reliably reusable, scaled by fleet slack.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // NEW: divisibility-aware residual shaping. Residuals that are multiples
    // of small common sizes (2, 4, 5, 10) recombine more easily later.
    if post_residual > 0 && post_residual <= 50 {
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        }
    }

    // NEW: waste-forecast term — penalize residuals that no plausible future
    // item (<= mean item proxy via mean residual scale) could ever use,
    // weighted by how much of the stream remains.
    if post_residual > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let usable_cap = (mean_residual * 2.0).max(20.0);
        if post_residual as f64 > usable_cap {
            score += ((post_residual as f64 - usable_cap) / bin_capacity as f64)
                * 12.0
                * (1.0 - progress);
        }
    }

    // NEW: pairing anticipation — reward bins where item + next item fit with
    // a small leftover, effectively pre-committing a two-item plan.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= 8.0;
        }
    }

    // NEW-BIN CANDIDATE handling with adaptive gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when other fits exist.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        // Gate on pooled slack covering the item comfortably.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never justify a fresh bin.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items: stricter fresh-bin gate when multiple bins fit.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bins attractive when next item is large and unhostable.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // Fresh-bin gate scaled by fleet slack ratio.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // NEW: late-stream fresh-bin suppression — as the stream nears its
        // end, opening new bins almost always wastes capacity; only allow it
        // when the item genuinely cannot fit anywhere else.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 15.0 + 30.0 * (progress - 0.6);
        }
        // NEW: early-stream fresh-bin encouragement for large items —
        // establishing a dedicated bin early preserves fleet residuals.
        if progress < 0.25 && item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: prefer bins whose residual stays usable for
    // common small items after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — penalize residuals in the awkward 31–40 band
    // when the fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: endgame exactness — in the final stretch, only near-exact fits
    // should win; add a graded penalty for any nonzero post residual.
    if progress > 0.9 && post_residual > 0 {
        score += (post_residual as f64).min(60.0) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let p = progress.clamp(0.0, 1.0);
    let poly = pr * pr * (1.0 + p * (1.0 - p) * 4.0);
    score += 0.002 * poly;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (0.5 + p);

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * p;
    }

    // Penalize new-bin candidate mildly, growing with progress
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * p;
    }

    // Lookahead: reward bins whose post_residual can hold next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 3.0 * (next_item_size as f64 / 100.0) * (1.0 - p * 0.5);
    }

    // Penalize bins far above mean residual (fragmentation)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

