        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // NEW: fit-quality gradient — prefer the tightest absolute fit among
    // candidates, scaled by how many alternatives exist (more choices,
    // more selective).
    if bin_residual != bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += waste * waste / (bin_capacity as f64 * 8.0) * (fitting_bins_count as f64).min(4.0).max(1.0) * 0.25;
    }

    score
}

