    // Fragmentation guard — awkward 31–40 band rarely fits common items
    // when the fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Pair-fit lookahead — residual + next item near a full bin signals a
    // future two-item seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if pair as f64 >= 0.95 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Waste-anticipation — residuals that host the next item but leave a
    // useless remainder (< 8) strand slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer-division bands of capacity/8 (8 "harmonics").
    let harm = post_residual / (bin_capacity / 8).max(1);
    score -= 6.0 * (harm as f64); // prefer bins leaving larger, reusable chunks

    // Perfect-fit harmonic: post_residual exactly divisible by common item sizes
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0; // leftover matches the smallest item class -> still usable
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Dead-space penalty: tiny unusable leftovers (harmonic class 0 or 1)
    if post_residual < bin_capacity / 8 {
        score += 18.0;
    } else if post_residual < bin_capacity / 4 {
        score += 7.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or near-exactly -> strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * (miss / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline offset that shrinks
    // as the stream progresses or when many bins are open (consolidate late).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 - 15.0 * progress - 0.5 * (open_bins_count.min(20) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild preference for bins whose residual is near the mean (balance load)
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Slight nudge toward tighter fits overall
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residual too small for the minimum item is wasted.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead: gap that cannot host the next item is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits, with a graded medium-tight tier.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    // Two-item lookahead chain: post_residual exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Chain lookahead: residual after next item would still host a third small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Last-chance pressure: sole fitting bin should generally absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure scaled by tightness of the fleet.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Dead-space ratio penalty — residual too small relative to typical
    // small items is likely stranded; scale penalty by how unusable it is.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Reward bins whose post-fit residual aligns with mean residual of the
    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // COMBINED: continuous dead-space shaping — smooth usability curve that
    // penalizes residuals too small to be reliably reusable, scaled by fleet
    // slack, layered on top of the parent's discrete tiers.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // New-bin candidate handling with sharper gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when the post-fit residual there would be
        // worse than the best open-bin post residual can be.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        // Stronger gate — if the fleet's mean residual comfortably covers
        // the item, opening a fresh bin wastes that pooled slack.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never justify a fresh bin when any
        // open bin fits them.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items also deserve a stricter fresh-bin gate when
        // multiple open bins fit — consolidation beats spreading.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bins are attractive when the next item is large and
        // no open bin could host it — leave the fleet residuals untouched.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // COMBINED: fresh-bin gate scaled by fleet slack ratio — opening a
        // bin is only acceptable if pooled residual barely exceeds the item.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
