    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: prefer bins whose residual stays usable for
    // common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — awkward 31–40 band rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead space penalty: small-but-nonzero leftovers are the worst waste.
    if post_residual > 0 {
        // Quadratic penalty for tiny residuals (< 10% capacity), the "unusable zone".
        if frac < 0.10 {
            score += 120.0 * (0.10 - frac) * 10.0;
        }
        // Modulo classes: residuals divisible by common item granularities
        // (multiples of 10, 5) are more reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 18.0;
        } else if r % 5 == 0 {
            score -= 8.0;
        }
        // Integer-division threshold classes on post_residual.
        let class = r / 10; // 0..10 harmonic class
        score += class as f64 * 3.0; // prefer leaving larger, more usable residual
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt = next_item_size as f64;
            let slack = (post_residual - next_item_size) as f64;
            if post_residual == next_item_size {
                score -= 220.0; // chained perfect fit
            } else {
                // Favor tight co-fit; penalize if leftover after next item is tiny.
                let post2 = slack;
                if post2 > 0.0 && post2 / cap < 0.05 {
                    score += 30.0;
                }
                score -= 40.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot fit here: mild penalty, this bin is a dead end soon.
            score += 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
        // But penalize wasting a nearly-full bin's last-chance on a bad fit.
        if post_residual > 0 && frac < 0.05 {
            score += 60.0;
        }
    }

    // Stream progression: early on, be more willing to spread items (open bins),
    // later consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (mean_residual / cap);

    // Prefer bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Default new-bin score slightly above a decent existing fit.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // Compete with last-chance bin: only win if that bin would be wrecked.
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
