pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space proportionally
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

