    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

