        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
