    // Reward tight fits: penalize proportionally to how much of the bin is wasted.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize unusable dead space: if post_residual is smaller than the smallest
    // plausible next item, that space is likely wasted.
    let dead = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
