    // stronger when the fleet is already tight (few alternatives remain).
    if post_residual > 25 && post_residual < 45 {
        let depth = 1.0 - ((post_residual as f64 - 25.0) / 20.0 - 0.5).abs() * 2.0;
        score += depth * 5.0 * (0.5 + tightness);
    }

    // NEW-bin candidate handling with sharper gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // Fresh-bin gate scaled by fleet slack ratio.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // NEW: late-stream fresh-bin discipline — near the end, opening a new
        // bin almost always wastes the pooled slack; only allow it for very
        // large items that no open bin could ever host.
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 18.0 * progress;
            if item_size as f64 <= 0.5 * bin_capacity as f64 {
                score += 15.0;
            }
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: prefer bins whose residual stays usable for
    // common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let norm_r = r / cap; // normalized post residual in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_n = mean_residual / cap;

    // Base: prefer small post residual (tight fits) with smooth non-linear shaping
    let mut score = 100.0 * norm_r * norm_r + 40.0 * norm_r;

    // Non-linear coupling of tightness with stream progress:
    // early on, tolerate slack (explore); late, demand tight fits (exploit)
    let tightness = 1.0 - norm_r; // 1 = perfect fit
    score -= 60.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize bins whose residual deviates strongly from the fleet mean (imbalance)
    let dev = norm_r - mean_n;
    score += 25.0 * dev * dev;

    // Lookahead coupling: smooth quadratic reward if next item fits the post residual
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64) / cap;
        score -= 35.0 * (-gap * gap).exp() * (1.0 - 0.5 * progress);
        // penalize leaving residual just barely below next item (dead space)
        if gap < 0.0 {
            score += 30.0 * gap * gap;
        }
    }

    // Scarcity pressure: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - progress);
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier about tightness
        score += 15.0 * norm_r;
    }

    // Mild penalty for proliferating bins when a decent fit exists
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_r;

    // New-bin candidate: make empty bin attractive only when no tight option likely exists
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - progress) + 30.0 * norm_r;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residual too small for the minimum item is wasted.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead: gap that cannot host the next item is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits, with a graded medium-tight tier.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    }

    // Two-item lookahead chain: post_residual exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Chain lookahead: residual after next item would still host a third small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 22.0;
        } else if r2 <= 5 {
            score -= 10.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

    // Last-chance pressure: sole fitting bin should generally absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure scaled by tightness of the fleet.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Dead-space ratio penalty — residual too small relative to typical
    // small items is likely stranded; scale penalty by how unusable it is.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.18 * tightness;
    }

    // Reward bins whose post-fit residual aligns with mean residual of the
    // fleet (harmonizes future mergeability of leftovers).
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Continuous dead-space shaping — smooth "usability curve" penalizing
    // residuals too small to be reliably reusable, scaled by fleet slack.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // New-bin candidate handling with sharper gating.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Mandatory fresh bin when nothing else fits.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Preserve room for a large next item if no open bin could host it.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            if mean_residual < next_item_size as f64 {
                score -= 12.0;
            }
        }
        // Prefer fresh bins for oversized items that would wreck an open bin's residual.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Penalize opening a bin when the post-fit residual there would be
        // worse than the best open-bin post residual can be.
        if fitting_bins_count > 1 {
            score += (item_size as f64 / bin_capacity as f64) * 10.0;
        }
        // Stronger gate — if the fleet's mean residual comfortably covers
        // the item, opening a fresh bin wastes that pooled slack.
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        // Small items should almost never justify a fresh bin when any
        // open bin fits them.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // Mid-size items also deserve a stricter fresh-bin gate when
        // multiple open bins fit — consolidation beats spreading.
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fresh bins are attractive when the next item is large and
        // no open bin could host it — leave the fleet residuals untouched.
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * bin_capacity as f64
            && mean_residual < next_item_size as f64
        {
            score -= 8.0;
        }
        // Fresh-bin gate scaled by fleet slack ratio — opening a bin is
        // only acceptable if the pooled residual barely exceeds the item.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // Fresh-bin option is excellent when the item nearly fills a fresh bin.
        if item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 18.0;
        }
    }

    // Tightness relative to the item being placed.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Stream-progress coupling: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }

    // Mid-stream refinement: gently prefer bins whose residual stays usable
    // for common small items (<= 30) after placement.
    if post_residual > 0 && post_residual <= 30 && progress < 0.85 {
        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early so that
    // later large items have landing spots; discourage over-tight fits early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation: reward bins whose residual is a multiple of
    // the next item size, enabling multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — when the fleet is loose, penalize residuals in
    // the awkward 31–40 band that rarely fits common items.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Pair-fit lookahead — reward placements leaving a residual which, with
    // the next item, nearly seals the bin.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if pair as f64 >= 0.95 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Waste-anticipation — penalize residuals larger than the next item but
    // leaving a useless remainder (< 8) after hosting it.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // NEW: triple-chain lookahead — when the next two placements could
    // exactly exhaust the residual (next item + a typical small complement),
    // reward the fit strongly; this compounds exact-chain opportunities.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 30 && mean_residual > 0.0 && (r2 as f64) <= mean_residual * 0.5 {
            score -= 3.5;
        }
    }

    // NEW: residual-variance-aware consolidation — when fleet residuals are
    // tightly clustered (low spread proxy via mean vs capacity), prefer bins
    // whose post residual matches the fleet mean exactly, enabling merges.
    if post_residual > 0 && mean_residual > 0.0 && open_bins_count > 3 {
        let diff = (post_residual as f64 - mean_residual).abs();
        if diff < 2.0 {
            score -= 2.5;
        } else if diff > 25.0 {
            score += 1.5;
        }
    }

    // NEW: threshold-band fit bonus — items that fit within a 3-unit margin
    // of the residual get a sharper bonus than the graded tiers alone,
    // since near-exact placements minimize stranded slack.
    if bin_residual >= item_size && bin_residual - item_size <= 3 {
        score -= 5.0 * (1.0 + 0.5 * (1.0 - tightness));
    }

    // NEW: large-item fresh-bin preference refinement — for items over 60%
    // of capacity, placing into an open bin leaves a residual smaller than
    // the item itself, which is often unusable; mildly discourage that.
    if item_size as f64 > 0.6 * bin_capacity as f64
        && bin_residual != bin_capacity
        && post_residual > 0
        && post_residual < item_size
    {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit leftover (decile bands) ----
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..=10 harmonic band
    let remainder = pr % 10;

    // Tiny leftovers (class 0, pr in 1..9) are dead space: penalize hard,
    // unless pr == 0 (perfect fit) which is the best outcome.
    if pr == 0 {
        score -= 60.0; // perfect fit reward
    } else if class == 0 {
        score += 25.0; // unusable sliver (1..9)
    } else if class == 1 {
        score += 8.0;  // 10..19: only fits tiny items
    } else if class == 2 || class == 3 {
        score -= 4.0;  // 20..39: decent mid-range pocket
    } else if class >= 5 {
        score += 3.0;  // large leftover: wasteful placement of a big item
    }

    // ---- Modulo coupling with next item: does the leftover "harmonize"? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: strong reward, scaled by tightness of that fit
            let next_gap = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.15 * next_gap;
            // extra harmony bonus if (post_residual - next) lands on a clean decile
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize by how close we are
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 6.0 + 0.4 * miss; // agonizing near-miss
            }
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, use it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin, but prefer it when existing
        // bins offer only poor fits (big items / many dead-end leftovers).
        let mut new_score = 45.0;
        if item_size >= 50 {
            new_score -= 10.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_score -= 12.0; // room for a paired second item
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            new_score -= 8.0; // open bins are nearly dead anyway
        }
        // Late in the stream, discourage proliferation of fresh bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 10.0 * progress;
        score = score.min(new_score).max(new_score.min(score));
        return new_score;
    }

    // ---- Tightness reward relative to current item ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // ---- Global residual pressure: keep mean residual low ----
    score += 0.05 * (mean_residual - post_residual as f64);

    // ---- Remainder tie-breaker (harmonic phase) ----
    score += 0.1 * remainder as f64;

    score
}

