        score -= 2.0 + (30 - post_residual) as f64 * 0.05;
    }

    // Early-stream conservation — keep bins open and loose early.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Exact-fit anticipation — residual a multiple of the next item size
    // enables multi-item exact chains.
    if next_item_size > 1 && bin_residual > next_item_size
        && bin_residual % next_item_size == 0
    {
        score -= 3.0;
    }

    // Fragmentation guard — awkward 31–40 band when the fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Pair-fit lookahead — reward residuals that, combined with the next
    // item, seal a near-full bin.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if pair as f64 >= 0.95 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Waste-anticipation — penalize residuals leaving a useless remainder
    // (< 8) after hosting the next item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible
    // future item are wasted capacity. Penalize them heavily.
    if post_residual > 0 {
        let dead = (post_residual as f64) < 10.0;
        if dead {
            score += 60.0;
        }
    }

    // Post-residual must also accommodate the lookahead item if possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // reward leaving room for the next item
        } else if post_residual > 0 {
            score += 25.0; // gap too small for lookahead: likely dead space
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit bonus: filling most of the bin is good
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the best
    // available fit would leave bad dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral baseline for a fresh bin
        score = bin_capacity as f64 - 20.0 + 0.8 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host current + next item together
        }
    }

    // Mild progression awareness: later in the stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect / graded near-perfect fit rewards.
    if post_residual == 0 {
        score -= 700.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    } else if post_residual <= 25 {
        score -= 4.0;
    }

    // Dead-space shaping: small unusable leftovers penalized smoothly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 8.0 * (0.5 + 0.5 * tightness);
        // Modulo reusability classes.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 14.0;
        } else if r % 5 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: next item cannot fit in the leftover — likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 35.0 + (next_item_size - post_residual) as f64 * 0.7;
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    }

    // Three-item chain: residual after next item still hosts a third item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 30.0;
        } else if r2 <= 5 {
            score -= 12.0;
        } else if r2 <= 12 {
            score -= 5.0;
        } else if r2 > 30 {
            score += 3.0;
        }
    }

    // Last-chance bonus: sole fitting bin should absorb unless fit is wrecked.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
        if post_residual > 0 && (post_residual as f64) / cap < 0.05 {
            score += 55.0;
        }
    }

    // Consolidation: prefer bins below fleet mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.35 + 0.4 * tightness);

    // Residual drift toward mean residual harmonizes mergeability.
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / cap).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Stream progression shaping.
    score += post_residual as f64 * progress * 0.3;
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.5;
    }
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        if item_size as f64 > 0.75 * cap {
            score -= 15.0;
        }
        // Small items should almost never open fresh bins.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fleet slack gate: opening a bin wasteful when pooled slack is ample.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // Preserve room for a large next item when fleet slack can't host it.
        if next_item_size > 0 && next_item_size as f64 > 0.55 * cap
            && next_item_size > item_size && mean_residual < next_item_size as f64 {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Fragmentation guard: awkward 31–40 band when fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation for multi-item chains.
    if next_item_size > 1 && bin_residual > next_item_size && bin_residual % next_item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 + (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: penalize dead space proportional to tightness.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize small unusable residual (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // New-bin candidate: make it moderately attractive only if current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
