        } else if next_item_size <= post_residual {
            score -= 100.0 + (post_residual - next_item_size) as f64;
            // Chain: residual after next item still usable for a small item.
            let r2 = post_residual - next_item_size;
            if r2 == 0 {
                score -= 60.0;
            } else if r2 <= 10 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize dead space proportional to tightness.
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 25.0;
        } else if post_residual <= 15 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.4;
    }

    // New-bin candidate: moderately attractive only if current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
