    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 25.0;
        } else if r2 <= 5 {
            score -= 12.0;
        } else if r2 <= 12 {
            score -= 4.0;
        } else if r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        } else if r2 > 30 {
            score += 2.0;
        }
    }

