    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 28.0;
        } else if post_residual <= 15 {
            score -= 8.0;
        } else if post_residual <= 25 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Stream-progress coupling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 9.0 + post_residual as f64 * progress * 0.2;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // Early-stream conservation: keep bins loose early.
    if progress < 0.3 && post_residual > 40 {
