    if post_residual > 0 {
        let remaining = (total_items - step_index) as f64;
        let unusable = if post_residual < next_item_size.max(1) as u32 { 1.0 } else { 0.0 };
        score += unusable * (remaining / total_items.max(1) as f64) * 12.0;
    }

    score
}

