    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction: penalize loose residuals harder near the end.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate: moderately attractive only if current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        // Fresh bin is wasteful when fleet slack can absorb many more items.
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // REFINED: fresh bin is wasteful when a single open bin nearly fits
        // the item tightly (gap <= 12) — sealing that bin is better.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 30.0;
        }
        // NEW: graded version — even moderately tight gaps discourage new bins.
        if fitting_bins_count >= 1 && best_gap <= 25.0 && best_gap < item_size as f64 * 0.4 {
            score += 12.0;
        }
        // NEW: fresh bin unattractive when the next item also fits leftover
        // fleet slack (avoid fragmenting future placements).
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 1 {
            score += 18.0;
        }
    }

    // Pair-fit seal: residual + next item nearly fills a bin.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: residual hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard: awkward band residuals.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation: residual multiple of next item enables chains.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened cubic so near-full bins dominate.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    // Extra penalty when dead space is small but nonzero and unusable.
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // When few bins fit, prefer emptiest-fitting bin to preserve flexibility.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward bins whose residual exactly matches next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Dead-space weakness: graded penalty for residuals that can never be
    // filled by the next item, scaled by remaining stream length.
    if post_residual > 0 {
        let remaining = (total_items - step_index) as f64;
        let unusable_pressure = if post_residual < next_item_size.max(1) as u32 { 1.0 } else { 0.0 };
        score += unusable_pressure * (remaining / total_items.max(1) as f64) * 12.0;
        // NEW: extend to residuals only slightly larger than next item that
        // would leave a sliver, early in the stream.
        if next_item_size > 0 && post_residual > next_item_size as u32 {
            let r2 = post_residual - next_item_size as u32;
            if r2 > 0 && r2 <= 3 {
                score += (4.0 - r2 as f64) * (remaining / total_items.max(1) as f64) * 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual is a multiple of a common small size -> very reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes of post_residual w.r.t. capacity fractions.
    // Leftovers in {0,10,20,25,50} are classic "friendly" residuals.
    let friendly: [u32; 6] = [0, 10, 20, 25, 50, 100];
    if friendly.contains(&post_residual) {
        score -= 30.0;
    }

    // Modulo-10 class: dead space under 10 is nearly unusable (min item size 10... but sizes 1..100 allowed).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // penalize tiny dead slivers
    }

    // Integer-division harmonic classes: post_residual / 10 quantization reward.
    let post_class = post_residual / 10;
    score -= (post_class as f64) * 2.0;

    // Coupling with next item: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // reward closeness of next item to post residual (harmonic alignment)
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 / (1.0 + gap)).min(50.0);
        } else {
            // next item cannot use this bin's leftover; penalize large leftover less if class-friendly
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Modulo coupling: post_residual % next_item_size == 0 means repeated fits possible.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer new bin only when item is large relative to capacity
    // and open bins have poor (fragmented) residuals.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap * 0.6;
        // open new bin if current item is big (harmonic class: > half capacity)
        if item_size * 2 > bin_capacity {
            score -= 40.0;
        }
        // if many bins fit the item, discourage opening a new one
        if fitting_bins_count > 2 {
            score += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        // if mean residual is high and can absorb item, discourage new bin
        if mean_residual > item_size as f64 * 1.2 {
            score += 50.0;
        }
        // early stream: keep bins open longer
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Mild penalty for leaving residual far from harmonic midpoints (25/50/75).
    let mid_dist = (post - 50.0).abs().min((post - 25.0).abs()).min((post - 75.0).abs());
    score += mid_dist * 0.1;

    // Small tie-break: prefer bins with less residual overall when many open.
    score += (open_bins_count as f64) * 0.01;

    score
}

