    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation: residual multiple of next item enables chains.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space shaping: near-full bins dominate.
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && fill > 0.95 {
        score += 6.0;
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // When few bins fit, prefer emptiest-fitting bin to preserve flexibility.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward bins whose residual exactly matches next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let remaining = (total_items - step_index) as f64;
        score += (remaining / total_items.max(1) as f64) * 12.0;
    }

    // NEW: smooth usability curve — penalize residuals too small to be
    // reliably reusable, scaled by how much slack the fleet already holds.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 6.0 * (1.0 - tightness);
    }

    // NEW: harmonize residuals with fleet mean — leftovers stay mergeable.
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / cap).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // NEW: early-stream conservation — keep bins loose early for later large items.
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 + (post_residual - next_item_size) as f64;
            let r2 = post_residual - next_item_size;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
        } else {
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when an open bin's residual exceeds item by a small amount
        // relative to next item's need too.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened cubic.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (refined: graded by gap).
    if post_residual > 0 {
        let remaining = (total_items - step_index) as f64;
        let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // NEW: residual-band risk — residuals in a sparse zone (far from typical item
    // multiples) accumulate dead space; penalize proportionally to fleet tightness.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify sub-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space before next item arrives.
            score += 8.0 + 0.25 * post_residual as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Bonus: this bin can also host the lookahead item.
            score -= 6.0;
            // Extra bonus for near-perfect two-item packing.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
    } else {
        // Last item: strongly prefer exact fill.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual > 50 {
            score += 10.0; // but not if it wastes half a bin
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current fit is poor and the stream has plenty left.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        let crowded = open_bins_count as f64 > 4.0 + 8.0 * (1.0 - progress);
        if poor_fit && crowded && next_item_size > post_residual {
            score -= 20.0; // open new bin for better long-run packing
        } else {
            score += 18.0; // default: discourage new bins
        }
    }

    // Mild penalty proportional to how far this bin's residual deviates
    // from the mean residual: prefer balanced bin usage.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Late in the stream, aggressively close out bins (favor small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
