    if post_residual > 0 {
        let pr = post_residual as f64;
        let usability = (pr / 30.0).min(1.0);
        score += (1.0 - usability) * (1.0 - usability) * 10.0 * (0.5 + 0.5 * tightness);
        let r = post_residual;
        if r % 10 == 0 {
            score -= 14.0;
        } else if r % 5 == 0 {
            score -= 6.0;
        }
        if r < 10 {
            score += 45.0;
        }
    }

    // Dead-space ratio term — sharpened cubic (borrowed from best).
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }

    // Lookahead: next item cannot fit in the leftover — likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let remaining = (total_items - step_index).max(1) as f64;
        let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
        score += (35.0 + (next_item_size - post_residual) as f64 * 0.8) * (0.4 + 0.6 * rem_frac);
    }

    // Two-item lookahead chain (strong exact-match reward).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 80.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Three-item chain: residual after next item still hosts a third item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 70.0;
        } else if r2 <= 5 {
            score -= 20.0;
        } else if r2 <= 12 {
            score -= 8.0;
        } else if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Pair-fit seal: residual + next item nearly fills bin.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Last-chance bonus: sole fitting bin should absorb unless fit is wrecked.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
        if post_residual > 0 && (post_residual as f64) / cap < 0.05 {
            score += 60.0;
        }
    }

    // Consolidation: prefer bins tighter than fleet mean residual.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Residual drift toward mean residual harmonizes mergeability.
    if post_residual > 0 && mean_residual > 0.0 {
        let drift = ((post_residual as f64 - mean_residual) / cap).abs();
        score -= (1.0 - drift.min(1.0)) * 4.0;
    }

    // Stream progression shaping.
    score += post_residual as f64 * progress * 0.3;
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }
    if progress < 0.3 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 60.0;
        }
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size as f64 > 0.75 * cap {
            score -= 15.0;
        }
        // Small items should almost never open fresh bins.
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if item_size > 20 && item_size <= 45 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Fleet slack gate: opening a bin wasteful when pooled slack is ample.
        if fitting_bins_count > 1 {
            let slack_ratio = mean_residual / (item_size as f64).max(1.0);
            if slack_ratio > 2.5 {
                score += (slack_ratio - 2.5).min(3.0) * 8.0;
            }
        }
        // Preserve room for a large next item when fleet slack can't host it.
        if next_item_size > 0 && next_item_size as f64 > 0.55 * cap
            && next_item_size > item_size && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when pooled slack hosts item + next item.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 0.8
            && fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Fragmentation guard: awkward 31–40 band when fleet is loose.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Residual-band risk: sparse zones accumulate dead space.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Exact-fit anticipation for multi-item chains.
    if next_item_size > 1 && bin_residual > next_item_size && bin_residual % next_item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: penalize wasted space quadratically (dead space grows costly).
    let mut score = post * (1.0 + 0.9 * norm_post);

    // Tight fits are valuable: reward small post_residual relative to item size.
    let tightness = 1.0 - (post / (item_size.max(1) as f64 + post));
    score -= 12.0 * tightness * tightness;

    // Smooth stream-progress coupling: as stream matures, prefer fuller bins.
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 8.0 * prog_term * norm_post;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item can use the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = post - nx;
            score -= 6.0 * (1.0 - waste / cap);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Divergence from mean residual: prefer bins that bring residual toward mean
    // (balance load across open bins, smooth non-linear penalty).
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Mild penalty for spreading across many bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - prog_term);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so as stream progresses.
        score += 6.0 + 14.0 * prog_term;
        // But if existing fitting bins are scarce and item is large, soften.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // A fresh bin is fine if the item is big (would leave small post anyway).
        score -= 4.0 * (item_size as f64 / cap);
    }

    score
}

