        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when an open bin's residual exceeds item+next.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        // NEW: when the fleet's mean residual can absorb both this item and the
        // next one, opening a fresh bin fragments the stream — penalize harder.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened quartic near-full fill.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    // NEW: extra reward for high-fill bins scaled by remaining stream length —
    // filling bins deeply early compounds savings across the stream.
    let remaining = (total_items - step_index) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (graded by gap).
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk — sparse zones accumulate dead space under tight fleets.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // NEW: next-item divisibility seal — if post_residual can be exactly split
    // by the next item's size (multi-item chain), reward the chain fit.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // NEW: coupling of residual to item size ratio — bins whose residual is a
    // small multiple of the item size are prime targets; slight reward.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "usable"
    // classes (large enough to host typical future items), penalize dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual by integer division into harmonic bands of capacity/5.
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_reward: f64 = match band {
        0 => -40.0,                     // tiny residue: nearly perfect fill
        1 => 0.0,                       // ~20% left: poor unless next item small
        2 => -10.0,                     // ~40% left: decent
        3 => -25.0,                     // ~60% left: good
        _ => -35.0,                     // mostly empty: almost like a new bin
    };
    score += band_reward;

    // Modulo-10 harmonic subclass: residuals divisible by 10 pair well with
    // items quantized to 10s; odd/prime residues create fragmentation.
    let m = post_residual % 10;
    let m_penalty: f64 = match m {
        0 => -6.0,
        1 | 9 => 5.0,
        2 | 8 => 3.0,
        5 => -2.0,
        _ => 1.0,
    };
    score += m_penalty;

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Reward chains: next item also fits here (harmonic chain bonus).
            score -= 12.0 + 0.15 * nx;
            // Extra bonus if post_residual - next is again a "clean" class.
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 || pr2 == 0 {
                score -= 8.0;
            }
        } else {
            // Penalize creating a residue that just misses the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 10.0 + gap; // near-miss dead space is worst
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it attractive only when residuals are
    // fragmented; otherwise bias toward reusing open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs();
        // Open new bin early or when mean residual is small (bins nearly full).
        score -= 20.0 * (1.0 - progress) + 0.2 * mean_residual;
        if mean_residual < 15.0 {
            score -= 15.0; // existing bins nearly saturated -> new bin good
        }
        if fragmentation > cap * 0.5 {
            score += 10.0;
        }
    }

    // Mild penalty for hoarding too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Small tie-breaker: prefer tighter fits (smaller post_residual already
    // dominates), add slight item-size-aware nudge.
    score += 0.05 * item_size as f64;

    score
}

