        score += (24 - post_residual) as f64 * 0.35 * (0.4 + rem_frac);
    }

    // NEW: lookahead trade-off — when the next item is large and no open bin
    // could host it (mean residual too small), prefer keeping the largest
    // residual intact: penalize placements that consume big residuals now.
