            && (fresh_post as f64) < 0.3 * cap
            && fleet_slack >= item_size as f64 {
            score += (0.3 * cap - fresh_post as f64) * 0.35;
        }
        // NEW: encourage a fresh bin for large items that leave a residual
        // well-matched to a likely small companion (residual in 1..=20).
        if fresh_post >= 1 && fresh_post <= 20 && next_item_size > 0
            && next_item_size <= fresh_post {
