                score += 30.0;
            }
        }
        // Count-based slack absorption — if total fleet slack comfortably
        // covers the item, discourage a new bin.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // NEW: fresh-bin future-waste estimate — the fresh bin's post-residual
        // will be stranded if it is smaller than the smallest plausible item
        // (approximated by mean item scale ~ item_size); penalize proportionally.
        let fresh_post = bin_capacity - item_size;
        if fresh_post < item_size {
            let stranded = fresh_post as f64;
            score += (stranded / cap) * 26.0 * rem_frac_calc(step_index, total_items);
        }
        // NEW: opening a fresh bin is cheaper when the fleet is nearly full
        // everywhere — reward when mean residual is very low.
        if mean_residual < 0.12 * cap && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
