    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream.
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // NEW (borrowed): dead-space efficiency — orphaned residual below next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // NEW (borrowed): nonlinear gap-to-mean compaction term.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // NEW (borrowed): late-stream tightest-bin consumption.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // NEW (borrowed): two-step seal for tiny remainders after next item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // NEW (borrowed): residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // NEW (borrowed): endgame squeeze — consume all residuals hard at the tail.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // NEW (borrowed): mid-gap guard under tight fleets.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // NEW (borrowed): harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // NEW: dead-space fill-rate refinement — reward post-residuals in the
    // plausible mid-size future-item band while stream work remains.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits (harmonic dead-space classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Modulo-10 harmonic class: fragmented residuals (r % 10 small but nonzero)
    // are less valuable than round residuals that chunkier items can reuse.
    let frag = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += frag * 0.6;
    }

    // Lookahead coupling: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover is reusable by the next item -> strong reward
            score -= 12.0;
            // extra reward for a perfect chain (post_residual == next_item_size)
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // leftover is dead space for the lookahead item
            score += 8.0;
            // integer-division harmonic class: how many times next item divides post_residual
            if next_item_size > 0 {
                let _ = post_residual / next_item_size;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer bins whose residual is far from the mean (consolidate fragmentation)
    score -= (mean_residual - post_residual as f64).abs() * 0.15;

    // Capacity-fraction class of the item: large items into large-residual bins
    let item_class = item_size / 25; // 0..3 harmonic class
    score += item_class as f64 * 2.0;

    // Stream progression: early on, be slightly more willing to open fresh bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; tuned so a new bin beats only bad fits.
        score = 55.0;
        // A new bin is more attractive for large items (hard to place later)
        score -= (item_size as f64) * 0.15;
        // If open bins are already fragmented (low mean residual), opening is better
        score -= (mean_residual.max(0.0) - 30.0) * 0.3;
        // If the next item is large, a fresh bin keeps flexibility
        if next_item_size > 60 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins
        score += progress * 10.0;
    }

    score
}

