        }
    }

    // NEW: near-perfect post-fit tiers — sharpen the sub-10 residual band
    // to squeeze out the last few bins of dead space.
    if post_residual > 0 && post_residual <= 10 {
        score -= (10.0 - post_residual as f64) * 1.6 * (0.5 + rem_frac);
    }

    // NEW: post-residual that exactly equals mean fleet slack is a refill
    // magnet — reward the match more strongly late in the stream.
    if post_residual > 0 && mean_residual > 0.0 {
        let dev = ((post_residual as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.1 {
            score -= 7.0 * (1.0 - dev / 0.1) * (0.4 + rem_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Derived context.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
