    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: dead-space waste integral — penalize residuals that no plausible
    // item (<= 100) can ever fill, scaled by remaining stream length.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let unreachable = (pr - 100.0).max(0.0);
        if unreachable > 0.0 {
            score += unreachable * (0.5 + rem_frac);
        }
