        for anchor in [20u32, 50u32, 80u32] {
            if pr < anchor as f64 && pr > (anchor as f64) * 0.5 {
                score += (anchor as f64 - pr) * 0.12 * (0.5 + tightness);
            }
        }
    }

    score
}

