        // is a permanent liability; penalize large stranded residuals when
        // the fleet already holds comparable slack.
        let fresh_post = cap - item_size as f64;
        if fresh_post > 0.0 && fresh_post < next_item_size.max(1) as f64 {
            let stranded = next_item_size as f64 - fresh_post;
