    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when an open bin's residual exceeds item+next.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0 + fitting_bins_count as f64 * 2.0;
        }
        let unabsorbed = (item_size as f64 - mean_residual).max(0.0);
        if unabsorbed > 0.0 {
            score -= (unabsorbed / cap) * 30.0;
        }
        // Opening a fresh bin is acceptable only if the fleet's mean
        // slack cannot even cover half the item; scale by coverage.
        let cover = (mean_residual / (item_size as f64).max(1.0)).min(2.0);
        if cover < 0.5 {
            score -= (0.5 - cover) * 60.0;
        }
        // If the next item would strand in a fresh bin while some open
        // bin's post-residual can host it, penalize opening a new bin.
        if next_item_size > 0 && next_item_size <= item_size {
            let fresh_post = bin_capacity - item_size;
            if next_item_size as f64 > fresh_post as f64
                && mean_residual - item_size as f64 >= next_item_size as f64 {
                score += 30.0;
            }
        }
        // Count-based slack absorption.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // NEW: fresh-bin residual should be a usable host for the next item —
        // if the fresh bin's post-residual exactly matches the next item,
        // opening is more attractive.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 22.0;
        }
        // NEW: avoid opening fresh bins whose leftover is a known dead zone
        // (small residuals unlikely to be refilled).
        let fresh_post = bin_capacity - item_size;
        if fresh_post > 0 && fresh_post < 12 && next_item_size > fresh_post {
            score += 18.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened quartic near-full fill.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (graded by gap).
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk — sparse zones accumulate dead space under tight fleets.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal — chain fits.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio — prime targets.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term — homogenize residuals for future items.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement — reward room for plausible mid-size
    // future items while substantial work remains.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Exact two-item seal — post_residual equals next item plus the
    // current item's size (perfect chain closure), sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: dead-space ratio refinement — penalize bins whose post-residual
    // leaves a stranded gap that no plausible future item (>= 1) can fill,
    // weighted by how much stream remains.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr > ns && (pr - ns) < 6.0 && rem_frac > 0.4 {
            score += (6.0 - (pr - ns)) * 0.8 * rem_frac;
        }
        // NEW: reward bins whose post-residual is within a tight window of
        // the next item — near-exact future seal.
        if (pr - ns).abs() <= 2.0 && pr >= ns {
            score -= 9.0 * (0.5 + rem_frac);
        }
    }

    // NEW: global compaction pressure — when fleet mean slack is small
    // relative to item size, push harder toward the tightest fits.
    if mean_residual < item_size as f64 && post_residual > 0 {
        score += (item_size as f64 - mean_residual) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Medium dead space (10..30) is mildly penalized since next items rarely fit.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Reward bins whose residual can still accommodate the lookahead item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for next item -> likely dead space
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the mean residual (better packing candidates).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to residual (poor fit in existing bins).
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) <= 5;
        if tight_fit {
            score -= 5.0; // fresh bin gives perfect-ish fit
        } else {
            score += 30.0 + item_size as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Derived context.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    let tightness = 1.0 - (mean_residual / cap).min(1.0);

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10.0 - post_residual as f64) * 3.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Open-bin pressure scaled by fleet tightness.
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0 + fitting_bins_count as f64 * 2.0;
        }
        let unabsorbed = (item_size as f64 - mean_residual).max(0.0);
        if unabsorbed > 0.0 {
            score -= (unabsorbed / cap) * 30.0;
        }
        let cover = (mean_residual / (item_size as f64).max(1.0)).min(2.0);
        if cover < 0.5 {
            score -= (0.5 - cover) * 60.0;
        }
        if next_item_size > 0 && next_item_size <= item_size {
            let fresh_post = bin_capacity - item_size;
            if next_item_size as f64 > fresh_post as f64
                && mean_residual - item_size as f64 >= next_item_size as f64 {
                score += 30.0;
            }
        }
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        let fresh_post = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && fresh_post < next_item_size as f64 && fresh_post < 0.12 * cap {
            score += 25.0;
        }
        // Fresh-bin residual quality: reward large reusable leftovers,
        // penalize stranded slivers, scaled by remaining stream.
        if fresh_post >= 0.4 * cap {
            score -= 14.0 * rem_frac;
        } else if fresh_post < 0.1 * cap && next_item_size > 0 {
            score += 18.0 * rem_frac;
        }
        // Fresh-bin lookahead pair: opening is cheap when the fresh bin can
        // host both this item and the next.
        if next_item_size > 0
            && (item_size + next_item_size) as f64 <= cap
            && fresh_post < next_item_size as f64 {
            score -= 20.0 * rem_frac;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream.
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Post-residual usability score.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let hosts_next = pr >= next_item_size as f64;
        let hosts_small = pr >= 0.2 * cap && pr <= 0.45 * cap;
        if hosts_next || hosts_small {
            score -= 10.0 * rem_frac;
        } else if pr < 0.2 * cap {
            score += 9.0 * rem_frac * (1.0 - pr / (0.2 * cap));
        }
    }

    // Exact two-item seal.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // Fine-grained fit + lookahead: perfect seal with few fitting bins.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
        score -= 12.0 * (0.5 + rem_frac);
    }

    // Dead-space budget: penalize residuals too small for the next item
    // but too large to be "perfect", weighted by remaining stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 0.15 * cap {
            score += deficit * 1.2 * rem_frac;
        }
    }

    // NEW: tight-fleet compaction — when the fleet is nearly full and the
    // item fits with small leftover, amplify the reward to squeeze out
    // extra bins at the end of the stream.
    if post_residual > 0 && tightness > 0.7 {
        let slack = post_residual as f64;
        if slack <= item_size as f64 {
            score -= (item_size as f64 - slack) * 0.8 * tightness * (0.5 + rem_frac);
        }
    }

    // NEW: fleet-slack conservation — when total fleet slack barely covers
    // the item, prefer placing it in the bin whose post-residual stays
    // most reusable (largest usable leftover), avoiding fragmentation.
    if post_residual > 0 && fitting_bins_count >= 2 {
        let fleet_total = mean_residual * open_bins_count as f64;
        if fleet_total < item_size as f64 * 2.5 && post_residual >= next_item_size.max(1) {
            score -= 6.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills leftover space -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how much lookahead matters (mid-stream)
            let progress = step_index as f64 / total_items.max(1) as f64;
            let lookahead_weight = 0.4 + 0.6 * progress;
            score += lookahead_gap * 0.35 * lookahead_weight;
            // If next item cannot fit in post_residual, it creates fragmentation pressure
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }
    }

    // Reward tight fits relative to mean residual (compact packing)
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist that fit well
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current item is large and no good fit exists
        if open_bins_count > 0 {
            score += 25.0;
            // If item nearly fills a bin, new bin is fine
            if item_size as f64 > 0.7 * bin_capacity as f64 {
                score -= 20.0;
            }
            // If next item is large too, pairing them in fresh bins is good
            if next_item_size as f64 > 0.6 * bin_capacity as f64 {
                score -= 10.0;
            }
        } else {
            score -= 50.0; // first bin must be opened
        }
    }

    // Slight preference to fill fuller bins first (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 520.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals (graded harder for very small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10.0 - post_residual as f64) * 3.0;
    }

    // Graded near-perfect tiers.
    if post_residual > 0 {
        if post_residual <= 5 {
            score -= 32.0;
        } else if post_residual <= 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 85.0;
    }

    // Prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Open-bin pressure scaled by fleet tightness.
    let tightness = 1.0 - (mean_residual / cap).min(1.0);
    score += open_bins_count as f64 * (0.3 + 0.4 * tightness);

    // Mild preference for using already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Late-stream compaction.
    if progress > 0.7 && post_residual > 10 {
        score += (post_residual as f64 - 10.0) * progress * 0.45;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        if item_size <= 20 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 2 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size
            && next_item_size as f64 > 0.55 * cap
            && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if item_size as f64 > 0.5 * cap
            && mean_residual < item_size as f64 * 1.2
            && fitting_bins_count >= 1 {
            score -= 35.0;
        }
        let slack_items = mean_residual / (item_size as f64).max(1.0);
        if slack_items > 3.0 && fitting_bins_count > 3 {
            score += 15.0;
        }
        // Seal bins with a tight near-fit gap instead of opening fresh.
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count >= 1 && best_gap <= 12.0 && best_gap < item_size as f64 * 0.25 {
            score += 32.0;
        }
        // Fresh bin wasteful when an open bin's residual exceeds item+next.
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 22.0;
        }
        if next_item_size > 0
            && mean_residual >= (item_size + next_item_size) as f64 * 1.1
            && fitting_bins_count >= 3 {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0 + fitting_bins_count as f64 * 2.0;
        }
        let unabsorbed = (item_size as f64 - mean_residual).max(0.0);
        if unabsorbed > 0.0 {
            score -= (unabsorbed / cap) * 30.0;
        }
        // Opening a fresh bin is acceptable only if the fleet's mean
        // slack cannot even cover half the item; scale by coverage.
        let cover = (mean_residual / (item_size as f64).max(1.0)).min(2.0);
        if cover < 0.5 {
            score -= (0.5 - cover) * 60.0;
        }
        // If the next item would strand in a fresh bin while some open
        // bin's post-residual can host it, penalize opening a new bin.
        if next_item_size > 0 && next_item_size <= item_size {
            let fresh_post = bin_capacity - item_size;
            if next_item_size as f64 > fresh_post as f64
                && mean_residual - item_size as f64 >= next_item_size as f64 {
                score += 30.0;
            }
        }
        // Count-based slack absorption.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // NEW: refuse a fresh bin when the fleet already holds enough total
        // slack to swallow this item AND the next one — force consolidation.
        if next_item_size > 0
            && fleet_slack >= (item_size + next_item_size) as f64
            && fitting_bins_count >= 2 {
            score += 26.0;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened quartic near-full fill.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 16.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (graded by gap).
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk — sparse zones accumulate dead space under tight fleets.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal — chain fits.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio — prime targets.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term — homogenize residuals for future items.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement — reward room for plausible mid-size
    // future items while substantial work remains.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Exact two-item seal — post_residual equals next item plus the
    // current item's size (perfect chain closure), sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: dead-space budget — penalize leaving residuals that no plausible
    // future item (bounded by the largest seen coupling) can absorb, scaled
    // by how much stream remains to potentially waste on them.
    if post_residual > 0 && rem_frac > 0.1 {
        let pr = post_residual as f64;
        let usable_ceiling = (next_item_size.max(item_size) as f64 + 15.0).min(cap);
        if pr > usable_ceiling {
            score += ((pr - usable_ceiling) / cap) * 22.0 * rem_frac;
        }
    }

    // NEW: residual clustering incentive — when several bins share similar
    // residuals, future mid-size items have more landing spots; reward
    // post_residuals close to the fleet mode proxy (mean_residual).
    if post_residual > 0 && open_bins_count >= 3 {
        let pr = post_residual as f64;
        let closeness = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= closeness * closeness * 4.0 * (0.5 + rem_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: strongly prefer minimal post_residual.
    score += (post_residual as f64) * 0.5;

    // Dead-space penalty: small post_residual that cannot fit typical items is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item;
    // penalize bins whose residual exactly matches next item (better saved? no—prefer use).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0; // chain-friendly bin
        }
        // If next item is large, prefer filling this bin now so big item opens fresh bin.
        if next_item_size >= item_size {
            score += (next_item_size - item_size) as f64 * 0.15;
        }
    } else {
        // Last item: any residual is pure waste; maximize fill.
        score -= (bin_capacity - post_residual) as f64 * 0.01;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalty proportional to how much of the bin is still empty (prefer fuller bins).
    score += (bin_residual as f64) * 0.3;

    // Global state coupling: many open bins with high mean residual -> consolidate,
    // avoid opening new bins (penalize new-bin candidate implicitly via residual term,
    // but add explicit pressure to use existing bins).
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in stream, be conservative (favor balanced residuals);
    // late in stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // existing bins fit poorly (large post_residuals) — add adaptive penalty.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64 + 1.0).ln();
        score += 20.0 + 30.0 * (1.0 - pressure.min(1.0));
        // If item is large relative to capacity, new bin is more acceptable.
        score -= item_size as f64 * 0.1;
    }

    // Mild tie-break noise-free coupling with item size: bigger items prefer emptier bins.
    score += item_size as f64 * 0.02 * (bin_residual as f64 / bin_capacity as f64);

    score
}

