    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Exact two-item seal — post_residual equals next item plus the
    // current item's size (perfect chain closure), sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: dead-space anticipation via quadratic fill curve — bins whose
    // post-residual sits in the awkward band (hard to fill with 1..100 items)
    // are penalized proportionally to remaining stream and fleet tightness.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let awkward = 1.0 - (pr / cap).min(1.0);
        let awkwardness = awkward * (1.0 - awkward) * 4.0; // peaks mid-residual
        if awkwardness > 0.9 {
            score += (awkwardness - 0.9) * 22.0 * rem_frac * (0.4 + tightness);
        }
    }

    // NEW: next-item stranding guard — if this bin's post-residual is the
    // only place the next item fits well, seal it firmly.
    if next_item_size > 0 && post_residual >= next_item_size
        && mean_residual < (item_size + next_item_size) as f64
        && fitting_bins_count <= 2 {
        score -= 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize unless no open bin fits or fits are poor.
    if bin_residual == bin_capacity {
        let mut penalty = 60.0;
        if fitting_bins_count == 0 {
            penalty = -50.0; // forced open
        } else if fitting_bins_count == 1 {
            penalty = 10.0;
        }
        // Early in stream, opening bins is cheaper (more future use).
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= (1.0 - progress) * 15.0;
        // Large next item favors fresh capacity.
        if next_item_size >= bin_capacity / 2 {
            penalty -= 20.0;
        }
        score += penalty;
        return score;
    }

    // Dead space: residuals too small for the smallest items are worthless.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic class match: reward when post_residual shares a residue class
    // with the next item (likely future fit).
    if next_item_size > 0 {
        let pr = post_residual;
        if next_item_size <= pr {
            // next item fits exactly after this placement: excellent
            score -= 25.0;
            if pr == next_item_size {
                score -= 30.0; // perfect closure
            }
        }
        // Modulo-10 class coupling: residuals in the same decade as next item
        // tend to combine well with mid-size follow-ups.
        let pr_class = pr / 10;
        let ni_class = next_item_size / 10;
        if pr_class == ni_class && next_item_size <= pr {
            score -= 8.0;
        }
        // Penalize leaving residual in awkward class (1..9 mod 10) if next item is large.
        if pr % 10 != 0 && next_item_size > pr {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer tighter fills relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Reward near-full packing.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Discourage many open bins with scattered residual: prefer consolidation.
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
