        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // COMBINED: residual-fit anticipation — when the current item leaves a
    // post-residual that tightly brackets the next item (small overshoot),
    // the bin is a prime compaction target; grade by overshoot ratio and
    // remaining stream, and couple to fleet tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let overshoot = (post_residual - next_item_size) as f64;
        let ratio = overshoot / (next_item_size as f64).max(1.0);
        if ratio <= 0.35 {
            score -= (0.35 - ratio) * 26.0 * (0.4 + rem_frac) * (0.5 + tightness);
        }
    }

    // COMBINED: dead-space floor — residuals in the awkward 26..34 band
    // rarely match typical item sizes; penalize more when the fleet is
    // tight (little slack elsewhere to absorb future items).
    if post_residual >= 26 && post_residual <= 34 && tightness > 0.6 {
        score += (34 - post_residual) as f64 * 0.55 * tightness;
    }

    // COMBINED: bin-consumption priority under few fits — when only a
    // couple of bins fit, prefer the one leaving the smallest absolute
    // post-residual to seal bins quickly and reduce open-bin count.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills this bin's post residual
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0).powi(6);
        // Extra bonus for perfect chain (post_residual == next_item_size)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual slightly larger than next item (wasted sliver)
        if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score += 8.0;
        }
        // Penalize residuals that can't hold next item and are small (dead space)
        if post_residual < next_item_size && post_residual < 10 {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins with residual below mean residual (compact bins first)
    let mean_diff = mean_residual - post_residual as f64;
    score -= 0.35 * mean_diff;

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild pressure to close bins early when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened unless rewarded by lookahead logic
        score += 18.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 35.0; // fresh bin chains perfectly with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals (graded harder for very small gaps).
