    if post_residual > 0 {
        let dfrac = post_residual as f64 / cap;
        score += dfrac * dfrac * 22.0 * rem_frac;
    }

    // MUTATION: variance-reduction targeting — prefer bins whose leftover
    // after placement stays close to the fleet mean, tightening residual
    // spread (lower sigma_res correlates with fewer wasted bins).
    if post_residual > 0 && open_bins_count > 3 {
        let dev2 = (post_residual as f64 - mean_residual).abs();
        if dev2 < 8.0 {
            score -= (8.0 - dev2) * 0.9 * rem_frac;
        }
    }

    score
}

