        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: two-step chain coverage — after hosting next item, can the
    // leftover still absorb the current item's size? Rewards deep chains.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= item_size.min(next_item_size) && r2 > 0 {
            score -= 9.0 * (0.4 + rem_frac);
        }
    }

    // NEW: dead-space budget — penalize post_residuals that fall in the
    // "hard to refill" band just below typical incoming item sizes.
    if post_residual > 0 && next_item_size > 0 && rem_frac > 0.15 {
        let pr = post_residual as f64;
        let nxt = next_item_size as f64;
        if pr < nxt && pr > nxt * 0.35 {
            score += (pr / nxt) * 10.0 * rem_frac;
        }
    }

    // NEW: near-exact refill anticipation — post_residual just above next
    // item leaves a sliver; grade by sliver size relative to capacity.
    if next_item_size > 0 && post_residual > next_item_size {
        let sliver = (post_residual - next_item_size) as f64;
        if sliver > 3.0 && sliver < 12.0 && tightness > 0.5 {
            score += (12.0 - sliver) * 0.9 * tightness;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fits are rewarded strongly (small post-residual preferred non-linearly)
    let fit_ratio = pr / cap;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Stream-progress coupling: late in the stream, prefer filling existing bins tighter
    let mean_r = mean_residual / cap;
    score += progress * 20.0 * fit_ratio * (1.0 - fit_ratio);
    score -= progress * 10.0 * mean_r * fit_ratio;

    // Reward leaving residual near the mean (balanced packing), smooth quadratic coupling
    let dev = (pr as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Mild penalty for opening new bins when many are open
    if bin_residual as f64 == cap {
        score += 12.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins that can host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            score -= 100.0 + r2 as f64;
            if r2 == 0 {
                score -= 70.0;
            } else if r2 <= 10 {
                score -= 25.0;
            }
            if r2 >= next_item_size {
                score -= 12.0;
            }
        } else {
            let tightness = 1.0 - (mean_residual / cap).min(1.0);
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * tightness);
        }
    }

    // Dead-space trap: tiny unusable residuals (graded harder for very small gaps).
