            }
        }
        // Count-based slack absorption.
        let fleet_slack = mean_residual * open_bins_count.min(8) as f64;
        if fleet_slack >= item_size as f64 * 2.0 && fitting_bins_count >= 1 {
            score += 12.0;
        }
        // NEW: fresh-bin penalty grows with the fraction of the fresh bin
        // that would be dead space after hosting item AND next item.
        if next_item_size > 0 {
            let fresh_post = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).max(0.0);
            if fresh_post > 0.0 && fresh_post < next_item_size as f64 {
                score += (next_item_size as f64 - fresh_post) * 0.4;
            }
        }
        // NEW: when many bins fit and fleet slack is ample, opening a new
        // bin is nearly always wasteful — scale penalty with fit count.
        if fitting_bins_count >= 4 && mean_residual >= item_size as f64 * 0.8 {
            score += 10.0 + fitting_bins_count as f64 * 1.5;
        }
    }

    // Pair-fit seal.
    if next_item_size > 0 && post_residual > 0 {
        let pair = post_residual + next_item_size;
        if (pair as f64) >= 0.95 * cap {
            score -= 14.0;
        }
    }

    // Waste-anticipation: hosting next item leaves a useless remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 < 8 {
            score += (8.0 - r2 as f64) * 0.6;
        }
    }

    // Fragmentation guard.
    if post_residual > 30 && post_residual < 40 && tightness < 0.5 {
        score += (40.0 - post_residual as f64) * 0.1;
    }

    // Exact-fit anticipation.
    if next_item_size > 1 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 4.0;
    }

    // Dead-space ratio term — sharpened quartic near-full fill.
    let fill = 1.0 - (post_residual as f64 / cap);
    let dead = 1.0 - fill;
    score -= fill * fill * fill * 18.0 + fill * 4.0;
    if post_residual > 0 && dead > 0.0 && dead < 0.05 {
        score += 6.0;
    }
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let rem_frac = (remaining / total_items.max(1) as f64).min(1.0);
    if post_residual > 0 && fill > 0.75 {
        score -= (fill - 0.75) * 14.0 * (0.5 + rem_frac);
    }

    // Mid-band residual penalty scaled by fleet slack.
    if post_residual > 20 && post_residual < 55 {
        score += (post_residual as f64 - 20.0) * 0.15 * (0.5 + tightness);
    }

    // Few fitting bins: prefer emptiest-fitting bin.
    if fitting_bins_count <= 3 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Reward residual matching next item plus small companion.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && mean_residual > r2 as f64 {
            score -= 6.0;
        }
    }

    // Unusable-residual pressure scaled by remaining stream (graded by gap).
    if post_residual > 0 {
        let nxt = next_item_size.max(1) as u32;
        if post_residual < nxt {
            score += (12.0 + (nxt - post_residual) as f64 * 0.8) * rem_frac;
        }
    }

    // Residual-band risk — sparse zones accumulate dead space under tight fleets.
    if post_residual > 0 {
        let zone = (post_residual as f64) % 25.0;
        if zone > 12.0 && zone < 20.0 && tightness > 0.55 {
            score += (20.0 - zone) * 0.5 * tightness;
        }
    }

    // Next-item divisibility seal — chain fits.
    if next_item_size > 1 && post_residual >= next_item_size
        && post_residual % next_item_size == 0 {
        let chain = post_residual / next_item_size;
        score -= (chain as f64) * 3.0;
    }

    // Coupling of residual to item size ratio — prime targets.
    if post_residual > item_size && item_size > 0 {
        let mult = post_residual as f64 / item_size as f64;
        if mult < 3.0 {
            score -= (3.0 - mult) * 2.5;
        }
    }

    // Dead-space efficiency.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 0.9 * rem_frac * (0.6 + tightness);
    }

    // Nonlinear dead-space term vs mean residual.
    let gap_to_mean = (mean_residual - post_residual as f64).max(0.0);
    if gap_to_mean > 0.0 {
        score -= (gap_to_mean * gap_to_mean) / (cap * 0.5);
    }

    // Late-stream: consume tightest bins.
    if progress > 0.5 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.5);
    }

    // Two-step seal.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 <= 3 {
            score -= 18.0 * rem_frac;
        }
    }

    // Dead-space variance control.
    if post_residual > 10 && post_residual < 25 && open_bins_count > 4 {
        score += (25.0 - post_residual as f64) * 0.4;
    }

    // Residual-to-next-item ratio compaction.
    if next_item_size > 1 && post_residual > next_item_size {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 2.0 {
            score -= (2.0 - ratio) * 7.0 * (0.5 + rem_frac);
        }
    }

    // Endgame squeeze.
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * (0.9 * (progress - 0.85) / 0.15) * 2.0;
    }

    // Mid-gap guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 8 && r2 <= 20 && tightness > 0.45 {
            score += r2 as f64 * 0.35 * (0.4 + tightness);
        }
    }

    // Three-item lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let proxy3 = (next_item_size as f64 + item_size as f64) * 0.5;
        if (r2 as f64) >= proxy3 && rem_frac > 0.3 {
            score -= ((r2 as f64 - proxy3) / cap) * 20.0 * rem_frac;
        }
    }

    // Waste-bucket sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < mean_residual {
            score += deficit * 0.25;
        } else {
            score += (deficit - mean_residual).min(30.0) * 0.5;
        }
    }

    // Harmonic residual decay.
    if post_residual > 0 {
        let decay = (post_residual as f64 / (item_size as f64 + post_residual as f64)) - 0.5;
        score += decay * 14.0 * (0.4 + tightness);
    }

    // Fleet-balance term — homogenize residuals for future items.
    if post_residual > 0 && open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += (dev / cap) * 10.0 * (open_bins_count.min(12) as f64 / 12.0);
    }

    // Dead-space fill-rate refinement — reward room for plausible mid-size
    // future items while substantial work remains.
    if post_residual > 0 && rem_frac > 0.25 {
        let pr = post_residual as f64;
        if pr >= 0.25 * cap && pr <= 0.5 * cap {
            score -= 8.0 * rem_frac * (0.5 + tightness);
        }
    }

    // Exact two-item seal — post_residual equals next item plus the
    // current item's size (perfect chain closure), sharpened late-stream.
    if next_item_size > 0 && post_residual > 0
        && post_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + rem_frac);
    }

    // Mean-residual coverage of post_residual — a bin whose leftover
    // matches the fleet's typical slack is easy to refill later.
    if post_residual > 0 && mean_residual > 0.0 {
        let cov = (post_residual as f64 / mean_residual).min(3.0);
        if cov < 1.0 {
            score -= (1.0 - cov) * 5.0 * rem_frac;
        }
    }

    // NEW: post-residual coverage by the next item — reward bins whose
    // leftover is an exact near-multiple of the next item's size, since
    // the fleet can chain multiple identical items into one gap.
    if next_item_size > 1 && post_residual > 0 {
        let chains = post_residual / next_item_size;
        let rem2 = post_residual % next_item_size;
        if chains >= 1 && rem2 <= 3 {
            score -= (chains as f64) * 2.5 + (3.0 - rem2 as f64) * 1.5 * rem_frac;
        }
    }

    // NEW: dead-space ratio penalty sharpened — bins whose post-residual
    // exceeds a quarter of capacity late in the stream waste real space;
    // scale the penalty with remaining stream length and fleet tightness.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr > 0.25 * cap && rem_frac < 0.75 {
            score += ((pr - 0.25 * cap) / cap) * 16.0 * (1.0 - rem_frac) * (0.5 + tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are prized (dead space is minimized).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer-division thresholds on post_residual: quarter classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if pr == 0 {
        score -= 30.0; // perfect fit is always best
    } else if pr < eighth {
        score -= 18.0; // near-perfect: unusable sliver, but tight packing
    } else if pr <= quarter {
        score -= 6.0; // small leftover still usable by tiny items
    } else if pr <= 2 * quarter {
        score += 4.0; // half-ish leftover: mediocre
    } else {
        score += 10.0; // large leftover: wasteful placement
    }

    // Modulo arithmetic: residuals that are multiples of small harmonics (4, 8)
    // are more likely to be exactly filled by future items of common sizes.
    if pr % 8 == 0 && pr > 0 {
        score -= 3.0;
    } else if pr % 4 == 0 && pr > 0 {
        score -= 1.5;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 1.0;
    }

    // Lookahead coupling: can next_item_size exactly fill or nest into post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == pr {
            score -= 20.0; // next item closes this bin exactly
        } else if next_item_size < pr {
            let r2 = pr - next_item_size;
            score -= (r2 as f64).min(15.0) * 0.4; // reward good nesting
            if r2 % 4 == 0 {
                score -= 2.0;
            }
        } else {
            score += 5.0; // next item won't fit here: less flexible bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // and mean residual is already fragmented.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin; make it attractive only if open bins are messy
        score -= 8.0 * (mean_residual / cap);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Fraction of capacity used by this placement: reward high fill ratio.
    let fill = item_size as f64 / cap;
    score -= fill * 10.0;

    // Stream progression: late in the stream, tighten packing (avoid leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 - progress * 3.0;

    // Prefer bins below mean residual (consolidate emptier bins first).
    score += (prf - mean_residual) * 0.05;

    score
}

