        }
    }

    // MUTATION: endgame — once few items remain, any residual smaller than
    // the smallest plausible future item is pure waste; squeeze it harder.
    if rem_frac < 0.1 && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // MUTATION: reward bins whose post_residual stays divisible-friendly:
    // a residual that is a near-exact multiple of a common small size
    // (item_size) will refill cleanly.
    if post_residual > 0 && item_size > 1 {
        let m = post_residual % item_size;
        if m == 0 && post_residual > item_size {
            score -= 3.0 + (post_residual / item_size).min(4) as f64;
        }
    }

    score
}
